INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('basic-research'::text, '{"en-us": "Basic research", "pt-br": "Pesquisa básica"}'::jsonb, '{"en-us": "Research conducted primarily to increase fundamental knowledge of biological, chemical or other phenomena, without an immediate practical or regulatory objective.", "pt-br": "Pesquisa realizada principalmente para ampliar o conhecimento fundamental sobre fenômenos biológicos, químicos ou outros, sem objetivo prático ou regulatório imediato."}'::jsonb, '1'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '1'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('translational-applied-research'::text, '{"en-us": "Translational and applied research", "pt-br": "Pesquisa translacional e aplicada"}'::jsonb, '{"en-us": "Research intended to apply or translate scientific knowledge toward a defined practical objective, including the prevention, diagnosis or treatment of disease and the improvement of human, animal or plant health and welfare.", "pt-br": "Pesquisa destinada a aplicar ou traduzir conhecimento científico para um objetivo prático definido, incluindo prevenção, diagnóstico ou tratamento de doenças e melhoria da saúde e do bem-estar humano, animal ou vegetal."}'::jsonb, '2'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '2'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('regulatory-use'::text, '{"en-us": "Regulatory use", "pt-br": "Uso regulatório"}'::jsonb, '{"en-us": "Use intended to generate information required, recommended or accepted by legislation or a regulatory authority for assessing the quality, safety, efficacy or environmental effects of a substance, product or intervention.", "pt-br": "Uso destinado a gerar informações exigidas, recomendadas ou aceitas pela legislação ou por uma autoridade regulatória para avaliar a qualidade, segurança, eficácia ou os efeitos ambientais de uma substância, produto ou intervenção."}'::jsonb, '3'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '3'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('routine-production'::text, '{"en-us": "Routine production", "pt-br": "Produção de rotina"}'::jsonb, '{"en-us": "Routine use associated with manufacturing, product consistency, quality control, potency testing or batch release, rather than research or initial method development.", "pt-br": "Uso rotineiro associado à fabricação, consistência do produto, controle de qualidade, ensaio de potência ou liberação de lotes, em vez de pesquisa ou desenvolvimento inicial de métodos."}'::jsonb, '4'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '4'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('environmental-protection'::text, '{"en-us": "Protection of the natural environment", "pt-br": "Proteção do meio ambiente natural"}'::jsonb, '{"en-us": "Use primarily intended to protect the natural environment in the interests of the health or welfare of humans, animals or ecological systems.", "pt-br": "Uso destinado principalmente a proteger o meio ambiente natural em benefício da saúde ou do bem-estar de seres humanos, animais ou sistemas ecológicos."}'::jsonb, '6'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '6'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('education-training'::text, '{"en-us": "Education and training", "pt-br": "Educação e treinamento"}'::jsonb, '{"en-us": "Use for teaching, demonstration or the acquisition, maintenance, improvement or assessment of academic, practical or professional knowledge and skills.", "pt-br": "Uso para ensino, demonstração ou aquisição, manutenção, aperfeiçoamento ou avaliação de conhecimentos e competências acadêmicas, práticas ou profissionais."}'::jsonb, '5'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-10-23 20:12:46.403356+00'::timestamp with time zone, '5'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('species-preservation'::text, '{"en-us": "Preservation of species", "pt-br": "Preservação de espécies"}'::jsonb, '{"en-us": "Research or other use primarily intended to support the conservation, recovery or continued survival of a species or population.", "pt-br": "Pesquisa ou outro uso destinado principalmente a apoiar a conservação, recuperação ou sobrevivência continuada de uma espécie ou população."}'::jsonb, '7'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '7'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('forensic-inquiry'::text, '{"en-us": "Forensic inquiry", "pt-br": "Investigação forense"}'::jsonb, '{"en-us": "Use in an investigation conducted primarily for legal, judicial, criminalistic or other forensic purposes.", "pt-br": "Uso em investigação realizada principalmente para fins legais, judiciais, criminalísticos ou outros fins forenses."}'::jsonb, '8'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '8'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('other'::text, '{"en-us": "Other", "pt-br": "Outro"}'::jsonb, '{"en-us": "A known purpose that is not represented by another value in this controlled vocabulary.", "pt-br": "Uma finalidade conhecida que não é representada por outro valor deste vocabulário controlado."}'::jsonb, '9'::integer, 'true'::boolean, '2026-08-15 12:46:04.109395+00'::timestamp with time zone, '2026-08-15 14:11:09.432085+00'::timestamp with time zone, '9'::integer);
INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") VALUES ('diagnostic-testing'::text, '{"en-us": "Diagnostic testing", "pt-br": "Teste diagnóstico"}'::jsonb, '{"en-us": "Use to detect, identify or confirm disease or an infectious agent in a diagnostic investigation.", "pt-br": "Uso para detectar, identificar ou confirmar doença ou agente infeccioso em uma investigação diagnóstica."}'::jsonb, '10'::integer, 'true'::boolean, '2026-10-09 16:53:09.48887+00'::timestamp with time zone, '2026-10-09 16:53:09.48887+00'::timestamp with time zone, '10'::integer);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('40'::integer, 'oecd-test-no-490-2016-07-29-in-vitro-mammalian-cell-gene-mutation-tests-using-the-thymi'::text, '{"en-us": "OECD (2016), Test No. 490: In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2016), Test No. 490: In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "Collection of OECD Test Guidelines for the testing of chemicals, covering in vitro gene mutation tests and skin sensitisation assays.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, abrangendo testes de mutação gênica in vitro e ensaios de sensibilização cutânea."}'::jsonb, '2016-07-29'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264908-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('41'::integer, 'oecd-test-no-494-2026-07-02-vitrigel-eye-irritancy-test-method-for-identifying-chemica'::text, '{"en-us": "OECD (2026), Test No. 494: Vitrigel-Eye Irritancy Test Method for Identifying Chemicals Not Requiring Classification and Labelling for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2026), Test No. 494: Vitrigel-Eye Irritancy Test Method for Identifying Chemicals Not Requiring Classification and Labelling for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "An OECD Test Guideline describing the Vitrigel-Eye Irritancy Test (EIT), an in vitro method using human corneal epithelium models to identify chemicals that do not require classification for eye irritation or serious eye damage based on changes in barrier function.", "pt-br": "Diretriz de Teste da OCDE que descreve o Teste de Irritação Ocular Vitrigel (EIT), um método in vitro que usa modelos de epitélio corneano humano para identificar substâncias químicas que não requerem classificação para irritação ocular ou lesões oculares graves, com base em alterações na função de barreira."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9f20068a-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('5'::integer, 'concea-rn-56-2022-10-05'::text, '{"en-us": "CONCEA (2022), Normative Resolution No. 56, October 5, 2022, Diário Oficial da União, Brazil.", "pt-br": "CONCEA (2022), Resolução Normativa nº 56, de 5 de outubro de 2022, Diário Oficial da União, Brasília."}'::jsonb, '{"en-us": "Official normative resolution recognizing and standardizing the use of validated alternative methods to animal use in research activities in Brazil, including OECD test guidelines for human health and biotic systems.", "pt-br": "Resolução normativa que reconhece e oficializa o uso de métodos alternativos validados ao uso de animais em atividades de pesquisa no Brasil, incluindo diretrizes de ensaio da OCDE para saúde humana e efeitos em sistemas bióticos."}'::jsonb, '2022-10-05'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.in.gov.br/web/dou/-/resolucao-n-56-de-5-de-outubro-de-2022-434544861'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('8'::integer, 'concea-rn-75-2026-01-22'::text, '{"en-us": "CONCEA (2026), Normative Resolution No. 75, January 22, 2026, Diário Oficial da União, Edição 16, Seção 1, Página 8, Brasília.", "pt-br": "CONCEA (2026), Resolução Normativa CONCEA nº 75, de 22 de janeiro de 2026, Diário Oficial da União, Edição 16, Seção 1, Página 8, Brasília."}'::jsonb, '{"en-us": "Recognizes alternative methods to the use of animals for rabies diagnosis, including DFA, dRIT, RT-PCR/RT-qPCR, and RTCIT. Establishes a five-year deadline for the mandatory replacement of the mouse inoculation test (MIT).", "pt-br": "Reconhece métodos alternativos ao uso de animais para o diagnóstico da raiva, incluindo DFA, dRIT, RT-PCR/RT-qPCR e RTCIT. Estabelece o prazo de cinco anos para a substituição obrigatória do teste de inoculação em camundongos (MIT)."}'::jsonb, '2026-01-22'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-75_2026-reconhece-metodo-alternativo-diagnostico-de-raiva-animal_dou-23-01-2026.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('12'::integer, 'oecd-test-no-420-2002-02-08-acute-oral-toxicity-fixed-dose-procedure'::text, '{"en-us": "OECD (2002), Test No. 420: Acute Oral Toxicity - Fixed Dose Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264070943-en.", "pt-br": "OECD (2002), Test No. 420: Acute Oral Toxicity - Fixed Dose Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264070943-en."}'::jsonb, '{"en-us": "The Fixed Dose Procedure is an acute oral toxicity test in which doses expected to be lethal are avoided. It uses a stepwise procedure to identify the dose causing evident toxicity or death, providing information for hazard classification according to the GHS.", "pt-br": "O Procedimento de Dose Fixa é um teste de toxicidade aguda oral no qual doses esperadas como letais são evitadas. Utiliza um procedimento gradual para identificar a dose que causa toxicidade evidente ou morte, fornecendo informações para a classificação de perigo conforme o GHS."}'::jsonb, '2002-02-08'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264070943-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('6'::integer, 'concea-rn-77-2026-07-22'::text, '{"en-us": "CONCEA (2026), Normative Resolution No. 77, July 22, 2026.", "pt-br": "CONCEA (2026), Resolução Normativa CONCEA nº 77, de 22 de julho de 2026, Reconhece método alternativo ao uso de animais para a detecção de endotoxinas bacterianas."}'::jsonb, '{"en-us": "This resolution formally recognizes the recombinant Factor C (rFC) method as an alternative to animal-based Limulus Amebocyte Lysate (LAL) testing for the detection of bacterial endotoxins, setting a five-year deadline for the mandatory transition.", "pt-br": "Esta resolução reconhece formalmente o método do Fator C recombinante (rFC) como alternativa ao uso do Lisado de Amebócitos de Limulus (LAL) para detecção de endotoxinas bacterianas, estabelecendo um prazo de cinco anos para a substituição obrigatória."}'::jsonb, '2026-07-22'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-77_2026-reconhece-metodo-alternativo_fator-c.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('2'::integer, 'concea-rn-45-2019-10-22'::text, '{"en-us": "CONCEA (2019), Normative Resolution No. 45, October 22, 2019", "pt-br": "CONCEA (2019), Resolução Normativa nº 45, de 22 de outubro de 2019"}'::jsonb, '{"en-us": "Recognizes the Monocyte Activation Test as an alternative method for evaluating pyrogenic contamination in injectable products, as part of the strategy to reduce, replace, or refine animal use in research.", "pt-br": "Reconhece o Teste de Ativação de Monócitos como método alternativo para avaliação de contaminação pirogênica em produtos injetáveis, visando a redução, substituição ou refinamento do uso de animais em pesquisa."}'::jsonb, '2019-10-22'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-45-de-22-de-outubro-de-2019.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('7'::integer, 'concea-rn-76-2026-02-06'::text, '{"en-us": "CONCEA (2026), Normative Resolution No. 76, February 6, 2026.", "pt-br": "CONCEA (2026), Resolução Normativa No. 76, de 6 de fevereiro, 2026."}'::jsonb, '{"en-us": "Resolution recognizing the OECD TG 492B method (Reconstructed Human Cornea-like Epithelium) for eye hazard identification in Brazil, establishing a five-year deadline for the replacement of animal-based methods.", "pt-br": "Resolução que reconhece o método OECD TG 492B (Epitélio semelhante à córnea humana) para avaliação de irritação e corrosão ocular no Brasil, estabelecendo prazo de cinco anos para a substituição de métodos que utilizam animais."}'::jsonb, '2026-02-06'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-76-de-6-de-fevereiro-de-2026-resolucao-concea-no-76-de-6-de-fevereiro-de-2026-dou-imprensa-nacional.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('1'::integer, 'farmacopeia-brasileira-7-I'::text, '{"en-us": "Farmacopeia Brasileira, 7ª edition: volume I - RDC version no 940/2024", "pt-br": "Farmacopeia Brasileira, 7ª edição: volume I - versão RDC nº 940/2024"}'::jsonb, '{"en-us": "The 7th edition of the Brazilian Pharmacopoeia (Anvisa, 2024) sets quality standards for pharmaceuticals in Brazil. Key highlights include the Monocyte Activation Test (replacing animal testing), international harmonization, 12 new texts, revisions, and consolidated updates.", "pt-br": "A 7ª edição da Farmacopeia Brasileira (Anvisa, 2024) estabelece padrões de qualidade farmacêutica no Brasil. Destaques incluem o Teste de Ativação de Monócitos (alternativo ao uso de animais), harmonização internacional, 12 novos textos, revisões técnicas e consolidação da 6ª edição."}'::jsonb, '2024-11-01'::date, '["method_protocol"]'::jsonb, '{"en-us": "Agência Nacional de Vigilância Sanitária (Anvisa), Brazil", "pt-br": "Agência Nacional de Vigilância Sanitária (Anvisa), Brasil"}'::jsonb, 'https://bibliotecadigital.anvisa.gov.br/jspui/handle/anvisa/11937'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('24'::integer, 'oecd-test-no-442a-2010-07-23-skin-sensitization-oecd-guidelines-for-the-testing-of-che'::text, '{"en-us": "OECD (2010), Test No. 442A: Skin Sensitization, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2010), Test No. 442A: Skin Sensitization, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines related to skin sensitisation, immunotoxicity, and cytochrome P450 induction, describing methods for chemical testing and regulatory assessment.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE relacionadas à sensibilização cutânea, imunotoxicidade e indução do citocromo P450, descrevendo métodos para a avaliação de substâncias químicas e a avaliação regulatória."}'::jsonb, '2010-07-23'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264090972-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('25'::integer, 'oecd-test-no-442b-2025-06-25-skin-sensitization-local-lymph-node-assay-brdu-elisa-or-f'::text, '{"en-us": "OECD (2025), Test No. 442B: Skin Sensitization: Local Lymph Node Assay: BrdU-ELISA or FCM, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 442B: Skin Sensitization: Local Lymph Node Assay: BrdU-ELISA or FCM, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "Guideline for identifying potential skin sensitizing test chemicals using a non-radioactive modification to the Local Lymph Node Assay based on BrdU content measurement in mouse lymph node cells.", "pt-br": "Diretriz para a identificação de substâncias químicas com potencial de sensibilização cutânea por meio de uma modificação não radioativa do Ensaio do Linfonodo Local, baseada na medição do conteúdo de BrdU em células de linfonodos de camundongo."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264090996-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('26'::integer, 'oecd-test-no-442c-2026-07-02-in-chemico-skin-sensitisation-oecd-guidelines-for-the-tes'::text, '{"en-us": "OECD (2026), Test No. 442C: In Chemico Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2026), Test No. 442C: In Chemico Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This Test Guideline provides in chemico methods addressing the Adverse Outcome Pathway key event on covalent binding to proteins for the skin sensitisation hazard endpoint.", "pt-br": "Esta Diretriz de Teste apresenta métodos in chemico que abordam o evento-chave da Rota de Resultado Adverso relativo à ligação covalente a proteínas, para o desfecho de perigo de sensibilização cutânea."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264229709-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('27'::integer, 'oecd-test-no-442d-2026-07-02-in-vitro-skin-sensitisation-oecd-guidelines-for-the-testi'::text, '{"en-us": "OECD (2026), Test No. 442D: In Vitro Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2026), Test No. 442D: In Vitro Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This Test Guideline provides five in vitro test methods addressing the keratinocyte activation Key Event on the Adverse Outcome Pathway for skin sensitisation, used for discriminating between skin sensitisers and non-sensitisers.", "pt-br": "Esta Diretriz de Teste apresenta cinco métodos de teste in vitro que abordam o evento-chave de ativação de queratinócitos na Rota de Resultado Adverso da sensibilização cutânea, utilizados para distinguir sensibilizantes de não sensibilizantes cutâneos."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264229822-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('28'::integer, 'oecd-test-no-442e-2026-07-02-in-vitro-skin-sensitisation-oecd-guidelines-for-the-testi'::text, '{"en-us": "OECD (2026), Test No. 442E: In Vitro Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2026), Test No. 442E: In Vitro Skin Sensitisation, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "An OECD test guideline addressing the human health hazard endpoint of skin sensitisation by providing four in vitro test methods that assess the activation of dendritic cells within the Adverse Outcome Pathway.", "pt-br": "Diretriz de teste da OCDE que aborda o desfecho de perigo à saúde humana de sensibilização cutânea, apresentando quatro métodos de teste in vitro que avaliam a ativação de células dendríticas na Rota de Resultado Adverso."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264359-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('39'::integer, 'oecd-test-no-473-2016-07-29-in-vitro-mammalian-chromosomal-aberration-test-oecd-guidel'::text, '{"en-us": "OECD (2016), Test No. 473: In Vitro Mammalian Chromosomal Aberration Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2016), Test No. 473: In Vitro Mammalian Chromosomal Aberration Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines for the testing of chemicals, focusing on genotoxicity and skin sensitisation pathways.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, com foco em genotoxicidade e nas rotas de sensibilização cutânea."}'::jsonb, '2016-07-29'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264649-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('11'::integer, 'oecd-gd-no-129-2010-07-20-guidance-document-on-using-cytotoxicity-tests-to-estimate-starting-doses-for-acu'::text, '{"en-us": "OECD (2010), Guidance Document on Using Cytotoxicity Tests to Estimate Starting Doses for Acute Oral Systematic Toxicity Tests, OECD Series on Testing and Assessment, No. 129, OECD Publishing, Paris, https://doi.org/10.1787/d77a7e39-en.", "pt-br": "OECD (2010), Guidance Document on Using Cytotoxicity Tests to Estimate Starting Doses for Acute Oral Systematic Toxicity Tests, OECD Series on Testing and Assessment, No. 129, OECD Publishing, Paris, https://doi.org/10.1787/d77a7e39-en."}'::jsonb, '{"en-us": "This guidance document details the use of in vitro basal cytotoxicity assays (using 3T3 or NHK cells) to predict LD50 values for the purpose of estimating starting doses for acute oral systemic toxicity tests, aiming to refine and reduce animal use.", "pt-br": "Este documento de orientação detalha o uso de ensaios de citotoxicidade basal in vitro (usando células 3T3 ou NHK) para prever valores de DL50 com o objetivo de estimar doses iniciais para testes de toxicidade sistêmica oral aguda, visando refinar e reduzir o uso de animais."}'::jsonb, '2010-07-20'::date, '["method_protocol", "guideline", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/d77a7e39-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('4'::integer, 'concea-rn-18-2014-09-24'::text, '{"en-us": "CONCEA (2014), Normative Resolution No. 18, September 24, 2014.", "pt-br": "CONCEA (2014), Resolução Normativa nº 18, de 24 de setembro de 2014."}'::jsonb, '{"en-us": "This normative resolution recognizes 17 alternative methods to the use of animals in research activities in Brazil, establishing a five-year deadline for the mandatory replacement of original methods with these validated alternatives.", "pt-br": "Esta resolução normativa reconhece 17 métodos alternativos ao uso de animais em atividades de pesquisa no Brasil, estabelecendo o prazo de até cinco anos para a substituição obrigatória dos métodos originais por estes métodos alternativos validados."}'::jsonb, '2014-09-24'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-18-de-24-de-setembro-de-2014.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('3'::integer, 'concea-rn-31-2016-08-18'::text, '{"en-us": "CONCEA (2016), Normative Resolution No. 31, August 18, 2016.", "pt-br": "CONCEA (2016), Resolução Normativa nº 31, de 18 de agosto de 2016, Reconhece métodos alternativos ao uso de animais em atividades de pesquisa no Brasil, Conselho Nacional de Controle de Experimentação Animal, Brasília."}'::jsonb, '{"en-us": "Brazilian normative resolution that recognizes seven internationally validated alternative methods for ocular irritation/corrosion, skin sensitization, reproductive toxicity, and pyrogenic contamination to reduce, replace, or refine animal use in research.", "pt-br": "Resolução normativa brasileira que reconhece sete métodos alternativos validados internacionalmente para irritação/corrosão ocular, sensibilização cutânea, toxicidade reprodutiva e contaminação pirogênica visando a redução, substituição ou refinamento do uso de animais em pesquisa."}'::jsonb, '2016-08-18'::date, '["regulation"]'::jsonb, '{"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}'::jsonb, 'https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-31-de-18-de-agosto-de-2016.pdf'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('13'::integer, 'oecd-test-no-423-2002-02-08-acute-oral-toxicity-acute-toxic-class-method'::text, '{"en-us": "OECD (2002), Test No. 423: Acute Oral toxicity - Acute Toxic Class Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071001-en.", "pt-br": "OECD (2002), Test No. 423: Acute Oral toxicity - Acute Toxic Class Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071001-en."}'::jsonb, '{"en-us": "The acute toxic class method is a stepwise procedure using a minimum number of animals to rank substances according to their acute oral toxicity by classifying them into one of several toxicity classes based on fixed LD50 cut-off values.", "pt-br": "O método da classe tóxica aguda é um procedimento escalonado que usa o número mínimo de animais para classificar substâncias segundo sua toxicidade oral aguda, enquadrando-as em uma de várias classes de toxicidade com base em valores de corte fixos de DL50."}'::jsonb, '2002-02-08'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071001-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('50'::integer, 'woah-manual-of-diagnostic-tests-and-vaccines-for-terrestrial-animals-10th-edition'::text, '{"en-us": "World Organisation for Animal Health. (2025). Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729", "pt-br": "World Organisation for Animal Health. (2025). Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729"}'::jsonb, '{"en-us": "The Terrestrial Manual provides internationally harmonised standards for laboratory diagnostic tests and the production and quality control of biological products (principally vaccines) for veterinary use to facilitate the surveillance, control, and international trade of animals.", "pt-br": "O Manual Terrestre estabelece normas harmonizadas internacionalmente para exames laboratoriais de diagnóstico e para a produção e o controle de qualidade de produtos biológicos (principalmente vacinas) de uso veterinário, com o objetivo de facilitar a vigilância, o controle e o comércio internacional de animais."}'::jsonb, '2025-01-01'::date, '["guideline", "method_protocol"]'::jsonb, '{"en-us": "World Organisation for Animal Health (WOAH)", "pt-br": "Organização Mundial da Saúde Animal (OIE)"}'::jsonb, 'https://doi.org/10.20506/woah.3729'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('20'::integer, 'oecd-test-no-435-2015-07-28-in-vitro-membrane-barrier-test-method-for-skin-corrosion-o'::text, '{"en-us": "OECD (2015), Test No. 435: In Vitro Membrane Barrier Test Method for Skin Corrosion, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2015), Test No. 435: In Vitro Membrane Barrier Test Method for Skin Corrosion, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "Compilation of OECD Test Guidelines for the testing of chemicals, including in vitro methods for skin corrosion, skin sensitisation, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Compilação de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, incluindo métodos in vitro para corrosão cutânea, sensibilização cutânea, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2015-07-28'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242791-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('29'::integer, 'oecd-test-no-460-2023-07-04-fluorescein-leakage-test-method-for-identifying-ocular-cor'::text, '{"en-us": "OECD (2023), Test No. 460: Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2023), Test No. 460: Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "An in vitro assay describing the Fluorescein Leakage test method to identify water soluble ocular corrosives and severe irritants as defined by the UN GHS Category 1.", "pt-br": "Ensaio in vitro que descreve o método de teste de vazamento de fluoresceína para identificar corrosivos oculares hidrossolúveis e irritantes graves, conforme definido pela Categoria 1 do GHS da ONU."}'::jsonb, '2023-07-04'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264185401-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('30'::integer, 'oecd-test-no-471-2020-06-29-bacterial-reverse-mutation-test-oecd-guidelines-for-the-te'::text, '{"en-us": "OECD (2020), Test No. 471: Bacterial Reverse Mutation Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2020), Test No. 471: Bacterial Reverse Mutation Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines for the testing of chemicals, focusing on toxicology and safety assessment methods including mutagenicity, skin sensitisation, immunotoxicity, and metabolic induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, com foco em métodos de toxicologia e avaliação de segurança, incluindo mutagenicidade, sensibilização cutânea, imunotoxicidade e indução metabólica."}'::jsonb, '2020-06-29'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071247-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('14'::integer, 'oecd-test-no-425-2022-06-30-acute-oral-toxicity-up-and-down-procedure'::text, '{"en-us": "OECD (2022), Test No. 425: Acute Oral Toxicity: Up-and-Down Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071049-en.", "pt-br": "OECD (2022), Test No. 425: Acute Oral Toxicity: Up-and-Down Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071049-en."}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines for the testing of chemicals, focusing on acute toxicity, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, com foco em toxicidade aguda, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2022-06-30'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071049-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('51'::integer, 'usp-86-bacterial-endotoxins-test-using-recombinant-reagents'::text, '{"en-us": "United States Pharmacopeia (USP). General Chapter <86> Bacterial Endotoxins Test Using Recombinant Reagents (proposed new chapter). Rockville: United States Pharmacopeial Convention.", "pt-br": "United States Pharmacopeia (USP). Capítulo geral <86> Bacterial Endotoxins Test Using Recombinant Reagents (proposta de novo capítulo). Rockville: United States Pharmacopeial Convention."}'::jsonb, '{"en-us": "Proposed USP chapter that adds alternative bacterial endotoxins techniques using nonanimal derived recombinant reagents (recombinant factor C or recombinant cascade reagent) to chapter <85>, with endpoint fluorescence or chromogenic detection.", "pt-br": "Proposta de capítulo da USP que acrescenta ao capítulo <85> técnicas alternativas de endotoxinas bacterianas com reagentes recombinantes não derivados de animais (fator C recombinante ou reagente em cascata recombinante), com detecção por fluorescência de ponto final ou cromogênica."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "United States Pharmacopeial Convention (USP)", "pt-br": "United States Pharmacopeial Convention (USP)"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('52'::integer, 'db-alm-protocol-131-episkin-skin-irritation-test'::text, '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 131: EpiSkin™ Skin Irritation Test 15 min - 42 hours.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 131: EpiSkin™ Skin Irritation Test 15 min - 42 hours."}'::jsonb, '{"en-us": "DB-ALM protocol of the EpiSkin skin irritation test (reconstructed human epidermis, MTT endpoint), cited among the reference models of OECD TG 439. The model is no longer commercially available. The file states no date.", "pt-br": "Protocolo do DB-ALM do teste de irritação cutânea EpiSkin (epiderme humana reconstruída, desfecho por MTT), citado entre os modelos de referência da TG 439 da OCDE. O modelo não está mais disponível comercialmente. O arquivo não informa data."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('53'::integer, 'db-alm-protocol-135-skinethic-skin-irritation-test'::text, '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 135: SkinEthic™ Skin Irritation Test.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 135: SkinEthic™ Skin Irritation Test."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic RHE skin irritation test (42 min application and 42 h post-incubation, MTT endpoint); the model is built from normal human keratinocytes in a chemically defined medium.", "pt-br": "Protocolo do DB-ALM do teste de irritação cutânea SkinEthic RHE (42 min de aplicação e 42 h de pós-incubação, desfecho por MTT); o modelo é feito de queratinócitos humanos normais em meio quimicamente definido."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('54'::integer, 'db-alm-protocol-164-epiocular-eye-irritation-test'::text, '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 164: Ocular Irritation Assay for Chemicals Using EpiOcular™ EIT.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 164: Ocular Irritation Assay for Chemicals Using EpiOcular™ EIT."}'::jsonb, '{"en-us": "DB-ALM protocol of the EpiOcular eye irritation test (reconstructed human cornea-like epithelium, MTT endpoint), a validated reference method of OECD TG 492. The model uses normal human foreskin-derived keratinocytes that are not transformed.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular EpiOcular (epitélio corneano humano reconstruído, desfecho por MTT), método de referência validado da TG 492 da OCDE. O modelo usa queratinócitos humanos normais derivados de prepúcio, não transformados."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('55'::integer, 'db-alm-protocol-190-skinethic-hce-eye-irritation-test-liquid'::text, '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 190: SkinEthic™ HCE Eye Irritation Test Liquid (EITL).", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 190: SkinEthic™ HCE Eye Irritation Test Liquid (EITL)."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic HCE eye irritation test for liquid and viscous chemicals, a validated reference method of OECD TG 492. The tissue comes from a transformed human corneal epithelial cell line in a chemically defined medium.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular SkinEthic HCE para líquidos e viscosos, método de referência validado da TG 492 da OCDE. O tecido vem de uma linhagem humana transformada de epitélio corneano em meio quimicamente definido."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('56'::integer, 'db-alm-protocol-191-skinethic-hce-eye-irritation-test-solid'::text, '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 191: SkinEthic™ HCE Eye Irritation Test Solid (EITS).", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 191: SkinEthic™ HCE Eye Irritation Test Solid (EITS)."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic HCE eye irritation test for solid chemicals, a validated reference method of OECD TG 492.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular SkinEthic HCE para sólidos, método de referência validado da TG 492 da OCDE."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('57'::integer, 'db-alm-skinethic-hce-time-to-toxicity-liquids-ttl'::text, '{"en-us": "SkinEthic™ HCE Time-to-Toxicity on Liquids SOP, Version 1 (2019) and Version 2 (June 2020). DB-ALM Protocol: In vitro eye hazard identification time-to-toxicity test method on liquids (TTL) using SkinEthic™ human corneal epithelium model (HCE).", "pt-br": "SOP SkinEthic™ HCE Time-to-Toxicity on Liquids, Versão 1 (2019) e Versão 2 (junho de 2020). Protocolo do DB-ALM: In vitro eye hazard identification time-to-toxicity test method on liquids (TTL) using SkinEthic™ human corneal epithelium model (HCE)."}'::jsonb, '{"en-us": "DB-ALM protocol (version 2, June 2020) of the SkinEthic HCE time-to-toxicity test for liquids, the SOP cited by OECD TG 492B. It classifies liquids into UN GHS No Category, Category 2 and Category 1 from three exposure times, and states that the model and its maintenance medium are proprietary to EPISKIN SA.", "pt-br": "Protocolo do DB-ALM (versão 2, junho de 2020) do teste de tempo até a toxicidade do SkinEthic HCE para líquidos, o SOP citado pela TG 492B da OCDE. Classifica líquidos em UN GHS Sem Categoria, Categoria 2 e Categoria 1 com base em três tempos de exposição, e informa que o modelo e seu meio de manutenção são proprietários da EPISKIN SA."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "L’Oréal Research & Innovation and EPISKIN SA, published in the EURL ECVAM DB-ALM", "pt-br": "L’Oréal Research & Innovation e EPISKIN SA, publicado no DB-ALM do EURL ECVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('58'::integer, 'db-alm-skinethic-hce-time-to-toxicity-solids-tts'::text, '{"en-us": "SkinEthic™ HCE Time-to-Toxicity on Solids SOP, Version 1 (June 25, 2019) and Version 2 (June 16, 2020). DB-ALM Protocol: In vitro eye hazard identification time-to-toxicity test method on solids (TTS) using SkinEthic™ human corneal epithelium model (HCE).", "pt-br": "SOP SkinEthic™ HCE Time-to-Toxicity on Solids, Versão 1 (25 de junho de 2019) e Versão 2 (16 de junho de 2020). Protocolo do DB-ALM: In vitro eye hazard identification time-to-toxicity test method on solids (TTS) using SkinEthic™ human corneal epithelium model (HCE)."}'::jsonb, '{"en-us": "DB-ALM protocol (version 2, 16 June 2020) of the SkinEthic HCE time-to-toxicity test for solids, the SOP cited by OECD TG 492B. It uses two exposure times (30 and 120 min).", "pt-br": "Protocolo do DB-ALM (versão 2, 16 de junho de 2020) do teste de tempo até a toxicidade do SkinEthic HCE para sólidos, o SOP citado pela TG 492B da OCDE. Usa dois tempos de exposição (30 e 120 min)."}'::jsonb, '2020-06-16'::date, '["method_protocol"]'::jsonb, '{"en-us": "L’Oréal Research & Innovation and EPISKIN SA, published in the EURL ECVAM DB-ALM", "pt-br": "L’Oréal Research & Innovation e EPISKIN SA, publicado no DB-ALM do EURL ECVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('59'::integer, 'jtec-labcyte-epi-model24-skin-irritation-test-sop-v8-3'::text, '{"en-us": "Japan Tissue Engineering Co., Ltd. (2011). In vitro skin irritation test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin irritation test-42 hours, Ver. 8.3 (June 2011). JSAAE skin irritation test validation study.", "pt-br": "Japan Tissue Engineering Co., Ltd. (2011). In vitro skin irritation test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin irritation test-42 hours, Ver. 8.3 (junho de 2011). Estudo de validação do teste de irritação cutânea da JSAAE."}'::jsonb, '{"en-us": "SOP of the LabCyte EPI-MODEL24 skin irritation test (OECD TG 439 model). States that the tissue is grown for 13 days in a medium with 5% fetal bovine serum from neonatal-foreskin keratinocytes expanded on 3T3-J2 feeder cells.", "pt-br": "SOP do teste de irritação cutânea LabCyte EPI-MODEL24 (modelo da TG 439 da OCDE). Informa que o tecido é cultivado por 13 dias em meio com 5% de soro fetal bovino, a partir de queratinócitos de prepúcio neonatal expandidos sobre células alimentadoras 3T3-J2."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('60'::integer, 'jtec-labcyte-epi-model24-skin-corrosion-test-sop-v1-6'::text, '{"en-us": "Japan Tissue Engineering Co., Ltd. (2017). In vitro skin corrosion test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin corrosion test, Version 1.6 (May 2017).", "pt-br": "Japan Tissue Engineering Co., Ltd. (2017). In vitro skin corrosion test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin corrosion test, Versão 1.6 (maio de 2017)."}'::jsonb, '{"en-us": "SOP of the LabCyte EPI-MODEL24 skin corrosion test. Same culture system as the irritation test: 5% fetal bovine serum and 3T3-J2 feeder cells.", "pt-br": "SOP do teste de corrosão cutânea LabCyte EPI-MODEL24. Mesmo sistema de cultura do teste de irritação: 5% de soro fetal bovino e células alimentadoras 3T3-J2."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('61'::integer, 'jacvam-labcyte-epi-model24-skin-corrosion-peer-review-report-2018'::text, '{"en-us": "JaCVAM Peer Review Panel (2018-10-26). Evaluation of the performance-based validation study on the LabCyte EPI-MODEL24 in vitro skin corrosion test method as a me-too test method according to OECD GD 219 and falling within the OECD TG 431.", "pt-br": "Painel de Revisão por Pares do JaCVAM (26/10/2018). Evaluation of the performance-based validation study on the LabCyte EPI-MODEL24 in vitro skin corrosion test method as a me-too test method according to OECD GD 219 and falling within the OECD TG 431."}'::jsonb, '{"en-us": "Peer review panel report on the LabCyte EPI-MODEL24 skin corrosion test as a me-too method. It documents the 5% foetal bovine serum in the production medium, the 3T3-J2 feeder cells and the serum batch checks.", "pt-br": "Relatório do painel de revisão por pares do teste de corrosão cutânea LabCyte EPI-MODEL24 como método \"me-too\". Documenta o soro fetal bovino a 5% no meio de produção, as células alimentadoras 3T3-J2 e as verificações de lote de soro."}'::jsonb, '2018-10-26'::date, '["other"]'::jsonb, '{"en-us": "Japanese Center for the Validation of Alternative Methods (JaCVAM)", "pt-br": "Centro Japonês para a Validação de Métodos Alternativos (JaCVAM)"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('62'::integer, 'jtec-labcyte-cornea-model24-eye-irritation-test-protocol-v2-7'::text, '{"en-us": "Japan Tissue Engineering Co., Ltd. (2018). In vitro eye irritation test using human corneal tissue model: LabCyte CORNEA-MODEL24 eye irritation test operation protocol, Ver. 2.7 (October 2018).", "pt-br": "Japan Tissue Engineering Co., Ltd. (2018). In vitro eye irritation test using human corneal tissue model: LabCyte CORNEA-MODEL24 eye irritation test operation protocol, Ver. 2.7 (outubro de 2018)."}'::jsonb, '{"en-us": "Operation protocol of the LabCyte CORNEA-MODEL24 eye irritation test (OECD TG 492 model). The tissue comes from normal human corneal epithelial cells of a donor cornea, expanded on 3T3-J2 feeder cells and cultured in a medium with 5% fetal bovine serum.", "pt-br": "Protocolo operacional do teste de irritação ocular LabCyte CORNEA-MODEL24 (modelo da TG 492 da OCDE). O tecido vem de células epiteliais corneanas humanas normais de córnea de doador, expandidas sobre células alimentadoras 3T3-J2 e cultivadas em meio com 5% de soro fetal bovino."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('63'::integer, 'kao-episensa-epidermal-sensitization-assay-sop-v2-6'::text, '{"en-us": "Kao Corporation (2022-08-22). Standard operating procedure: EpiSensA, Epidermal Sensitization Assay, Version 2.6.", "pt-br": "Kao Corporation (22/08/2022). Standard operating procedure: EpiSensA, Epidermal Sensitization Assay, Versão 2.6."}'::jsonb, '{"en-us": "SOP of the EpiSensA epidermal sensitisation assay (OECD TG 442D). It uses the LabCyte EPI-MODEL24 kit from J-TEC (normal human epidermal keratinocytes) and measures four marker genes by real-time PCR.", "pt-br": "SOP do ensaio de sensibilização epidérmica EpiSensA (TG 442D da OCDE). Usa o kit LabCyte EPI-MODEL24 da J-TEC (queratinócitos epidérmicos humanos normais) e mede quatro genes marcadores por PCR em tempo real."}'::jsonb, '2022-08-22'::date, '["method_protocol"]'::jsonb, '{"en-us": "Kao Corporation and JaCVAM", "pt-br": "Kao Corporation e JaCVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('64'::integer, 'kocvam-keraskin-phototoxicity-assay-sop-v1-3'::text, '{"en-us": "Kang, N.H. (2025-11-26). Standard operating procedure: KeraSkin™ Phototoxicity Assay, Version 1.3. Korean Center for the Validation of Alternative Methods (KoCVAM), National Institute of Food and Drug Safety Evaluation.", "pt-br": "Kang, N.H. (26/11/2025). Standard operating procedure: KeraSkin™ Phototoxicity Assay, Versão 1.3. Centro Coreano para a Validação de Métodos Alternativos (KoCVAM), Instituto Nacional de Avaliação da Segurança de Alimentos e Medicamentos."}'::jsonb, '{"en-us": "SOP of the KeraSkin phototoxicity assay, a me-too method to the EpiDerm phototoxicity test, cited by OECD TG 498. The tissue is made of primary cultured human keratinocytes of Korean origin; the SOP does not describe the medium composition.", "pt-br": "SOP do ensaio de fototoxicidade KeraSkin, método \"me-too\" do teste de fototoxicidade EpiDerm, citado pela TG 498 da OCDE. O tecido é feito de queratinócitos humanos primários de origem coreana; o SOP não descreve a composição do meio."}'::jsonb, '2025-11-26'::date, '["method_protocol"]'::jsonb, '{"en-us": "Korean Center for the Validation of Alternative Methods (KoCVAM), National Institute of Food and Drug Safety Evaluation", "pt-br": "Centro Coreano para a Validação de Métodos Alternativos (KoCVAM), Instituto Nacional de Avaliação da Segurança de Alimentos e Medicamentos"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('65'::integer, 'biosolution-mctt-hce-eye-irritation-test-sop-v1-8'::text, '{"en-us": "Biosolution Co., Ltd. (2024-01-22). In vitro eye irritation test with a reconstructed human cornea-like epithelium test method, MCTT HCE™. SOP Version 1.8.", "pt-br": "Biosolution Co., Ltd. (22/01/2024). In vitro eye irritation test with a reconstructed human cornea-like epithelium test method, MCTT HCE™. SOP Versão 1.8."}'::jsonb, '{"en-us": "SOP of the MCTT HCE eye irritation test (OECD TG 492 model), in Korean. The tissue is made of normal human corneal epithelial cells; the SOP does not describe the medium composition or mention serum.", "pt-br": "SOP do teste de irritação ocular MCTT HCE (modelo da TG 492 da OCDE), em coreano. O tecido é feito de células epiteliais corneanas humanas normais; o SOP não descreve a composição do meio nem cita soro."}'::jsonb, '2024-01-22'::date, '["method_protocol"]'::jsonb, '{"en-us": "Biosolution Co., Ltd. (Korea), with KoCVAM", "pt-br": "Biosolution Co., Ltd. (Coreia), com o KoCVAM"}'::jsonb, NULL, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('31'::integer, 'oecd-test-no-476-2016-07-29-in-vitro-mammalian-cell-gene-mutation-tests-using-the-hprt'::text, '{"en-us": "OECD (2016), Test No. 476: In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2016), Test No. 476: In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines for in vitro testing, covering genetic mutation assays, skin sensitisation, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para testes in vitro, abrangendo ensaios de mutação gênica, sensibilização cutânea, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2016-07-29'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264809-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('32'::integer, 'oecd-test-no-487-2023-07-04-in-vitro-mammalian-cell-micronucleus-test-oecd-guidelines-'::text, '{"en-us": "OECD (2023), Test No. 487: In Vitro Mammalian Cell Micronucleus Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2023), Test No. 487: In Vitro Mammalian Cell Micronucleus Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "An in vitro genotoxicity test for the detection of micronuclei originating from acentric chromosome fragments or whole chromosomes in interphase cells.", "pt-br": "Teste de genotoxicidade in vitro para a detecção de micronúcleos originados de fragmentos cromossômicos acêntricos ou de cromossomos inteiros em células em interfase."}'::jsonb, '2023-07-04'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264861-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('9'::integer, 'oecd-test-no-492b-2024-06-25-reconstructed-human-cornea-like-epithelium'::text, '{"en-us": "OECD (2024), Test No. 492B: Reconstructed Human Cornea-like Epithelium (RHCE) Test Method for Eye Hazard Identification, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/0d603916-en.", "pt-br": "OECD (2024), Test No. 492B: Reconstructed Human Cornea-like Epithelium (RHCE) Test Method for Eye Hazard Identification, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/0d603916-en."}'::jsonb, '{"en-us": "This Test Guideline describes an in vitro procedure using reconstructed human cornea-like epithelium (RhCE) to identify chemicals not requiring classification, requiring classification for eye irritation (Cat 2), or serious eye damage (Cat 1) based on UN GHS ocular hazard categories.", "pt-br": "Esta Diretriz de Teste descreve um procedimento in vitro utilizando epitélio semelhante à córnea humana reconstruído (RhCE) para identificar substâncias que não requerem classificação, que requerem classificação para irritação ocular (Cat 2) ou dano ocular grave (Cat 1) conforme o GHS da ONU."}'::jsonb, '2024-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/0d603916-en'::text, '{57,58}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('16'::integer, 'oecd-test-no-429-2026-07-02-skin-sensitisation-local-lymph-node-assay'::text, '{"en-us": "OECD (2026), Test No. 429: Skin Sensitisation: Local Lymph Node Assay, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2026), Test No. 429: Skin Sensitisation: Local Lymph Node Assay, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "Guideline detailing the Local Lymph Node Assay for skin sensitisation, including performance standards and animal-reduced options, alongside listing various other OECD Test Guidelines.", "pt-br": "Diretriz que descreve o Ensaio do Linfonodo Local para sensibilização cutânea, incluindo padrões de desempenho e opções com redução do uso de animais, além de listar diversas outras Diretrizes de Teste da OCDE."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071100-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('17'::integer, 'oecd-test-no-430-2015-07-28-in-vitro-skin-corrosion-transcutaneous-electrical-resistan'::text, '{"en-us": "OECD (2015), Test No. 430: In Vitro Skin Corrosion:Transcutaneous Electrical Resistance Test Method (TER), OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2015), Test No. 430: In Vitro Skin Corrosion:Transcutaneous Electrical Resistance Test Method (TER), OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "Collection of OECD Test Guidelines for the testing of chemicals covering endpoints such as skin corrosion, skin sensitisation, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, abrangendo desfechos como corrosão cutânea, sensibilização cutânea, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2015-07-28'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242739-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('10'::integer, 'european-pharmacopoeia-2.6.32-test-bacterial-endotoxins-using-recombinant-factor-C'::text, '{"en-us": "European Pharmacopoeia. 2.6.32 Test for bacterial endotoxins using recombinant factor C. 10.3 ed. Strasbourg: Council of Europe, 2021.", "pt-br": "European Pharmacopoeia. 2.6.32 Test for bacterial endotoxins using recombinant factor C. 10.3 ed. Strasbourg: Council of Europe, 2021."}'::jsonb, '{"en-us": "Compendial method using recombinant factor C (rFC) and fluorimetric detection to detect or quantify bacterial endotoxins, as an alternative to tests using horseshoe crab-derived lysate.", "pt-br": "Método compendial que utiliza fator C recombinante (rFC) e detecção fluorimétrica para detectar ou quantificar endotoxinas bacterianas, como alternativa a ensaios que utilizam lisado derivado de caranguejos-ferradura."}'::jsonb, '2021-01-01'::date, '["method_protocol"]'::jsonb, '{"en-us": "European Directorate for the Quality of Medicines & HealthCare (EDQM), Council of Europe", "pt-br": "European Directorate for the Quality of Medicines & HealthCare (EDQM), Conselho da Europa"}'::jsonb, 'https://pheur-online.edqm.eu/home/'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('18'::integer, 'oecd-test-no-431-2025-06-25-in-vitro-skin-corrosion-reconstructed-human-epidermis-rhe-'::text, '{"en-us": "OECD (2025), Test No. 431: In vitro skin corrosion: reconstructed human epidermis (RHE) test method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 431: In vitro skin corrosion: reconstructed human epidermis (RHE) test method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "Guideline for identifying corrosive chemical substances and mixtures using a three-dimensional human skin model (reconstructed human epidermis) without the use of live animals.", "pt-br": "Diretriz para a identificação de substâncias e misturas químicas corrosivas usando um modelo tridimensional de pele humana (epiderme humana reconstruída), sem o uso de animais vivos."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264618-en'::text, '{60,61}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('19'::integer, 'oecd-test-no-432-2019-06-18-in-vitro-3t3-nru-phototoxicity-test-oecd-guidelines-for-th'::text, '{"en-us": "OECD (2019), Test No. 432: In Vitro 3T3 NRU Phototoxicity Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2019), Test No. 432: In Vitro 3T3 NRU Phototoxicity Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This document describes an in vitro method to evaluate phototoxicity using 3T3 cells by comparing cell viability in the presence and absence of light exposure.", "pt-br": "Este documento descreve um método in vitro para avaliar a fototoxicidade em células 3T3, comparando a viabilidade celular na presença e na ausência de exposição à luz."}'::jsonb, '2019-06-18'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071162-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('22'::integer, 'oecd-test-no-438-2023-07-04-isolated-chicken-eye-test-method-for-identifying-i-chemica'::text, '{"en-us": "OECD (2023), Test No. 438: Isolated Chicken Eye Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2023), Test No. 438: Isolated Chicken Eye Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "An in vitro test method for eye hazard classification using enucleated chicken eyes to identify serious eye damage or non-classified substances, eliminating the need for laboratory animals.", "pt-br": "Método de teste in vitro para a classificação de perigo ocular que utiliza olhos de galinha enucleados para identificar substâncias que causam lesões oculares graves ou não classificadas, eliminando a necessidade de animais de laboratório."}'::jsonb, '2023-07-04'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264203860-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('15'::integer, 'oecd-test-no-428-2004-11-23-skin-absorption-in-vitro-method'::text, '{"en-us": "OECD (2004), Test No. 428: Skin Absorption: In Vitro Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071087-en.", "pt-br": "OECD (2004), Test No. 428: Skin Absorption: In Vitro Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071087-en."}'::jsonb, '{"en-us": "Collection of internationally recognized test guidelines for the testing of chemicals, focusing on in vitro methods for percutaneous absorption, skin sensitisation, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de diretrizes de teste reconhecidas internacionalmente para a avaliação de substâncias químicas, com foco em métodos in vitro para absorção percutânea, sensibilização cutânea, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2004-11-23'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264071087-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('21'::integer, 'oecd-test-no-437-2025-06-25-bovine-corneal-opacity-and-permeability-test-method-for-id'::text, '{"en-us": "OECD (2025), Test No. 437: Bovine Corneal Opacity and Permeability Test Method for Identifying chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 437: Bovine Corneal Opacity and Permeability Test Method for Identifying chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "An in vitro test method using isolated cattle corneas to identify chemicals that cause serious eye damage or do not require classification for eye irritation or serious eye damage according to GHS, serving as an alternative to laboratory animal testing.", "pt-br": "Método de teste in vitro que utiliza córneas bovinas isoladas para identificar substâncias químicas que causam lesões oculares graves ou que não requerem classificação para irritação ocular ou lesões oculares graves segundo o GHS, servindo como alternativa ao teste em animais de laboratório."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264203846-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('23'::integer, 'oecd-test-no-439-2025-06-25-in-vitro-skin-irritation-reconstructed-human-epidermis-tes'::text, '{"en-us": "OECD (2025), Test No. 439: In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 439: In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "An OECD Test Guideline describing an in vitro procedure using reconstructed human epidermis (RhE) for the hazard identification of irritant chemicals (UN GHS Category 2), serving as a stand-alone or partial replacement for in vivo testing.", "pt-br": "Diretriz de Teste da OCDE que descreve um procedimento in vitro com epiderme humana reconstruída (RhE) para a identificação de perigo de substâncias químicas irritantes (Categoria 2 do GHS da ONU), servindo como substituição independente ou parcial do teste in vivo."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242845-en'::text, '{52,53,59}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('33'::integer, 'oecd-test-no-492-2025-06-25-reconstructed-human-cornea-like-epithelium-rhce-test-metho'::text, '{"en-us": "OECD (2025), Test No. 492: Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 492: Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "OECD Test Guideline for an in vitro procedure using RhCE tissue constructs to identify chemicals that do not require classification and labelling for eye irritation or serious eye damage according to UN GHS.", "pt-br": "Diretriz de Teste da OCDE para um procedimento in vitro com construtos de tecido RhCE, que identifica substâncias químicas que não requerem classificação e rotulagem para irritação ocular ou lesões oculares graves segundo o GHS da ONU."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242548-en'::text, '{54,55,56,62,65}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('34'::integer, 'oecd-test-no-491-2025-06-25-short-time-exposure-in-vitro-test-method-for-identifying-i'::text, '{"en-us": "OECD (2025), Test No. 491: Short Time Exposure In Vitro Test Method for Identifying i)Chemicals Inducing Serious Eye Damageand ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2025), Test No. 491: Short Time Exposure In Vitro Test Method for Identifying i)Chemicals Inducing Serious Eye Damageand ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "Collection of OECD Test Guidelines for the testing of chemicals, focusing on in vitro methods for ocular damage, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, com foco em métodos in vitro para dano ocular, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242432-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('35'::integer, 'oecd-test-no-455-2026-07-02-performance-based-test-guideline-for-stably-transfected-tr'::text, '{"en-us": "OECD (2026), Test No. 455: Performance ‑ Based Test Guideline for Stably Transfected Transactivation In Vitro Assays to Detect Estrogen Receptor Agonists and Antagonists, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2026), Test No. 455: Performance ‑ Based Test Guideline for Stably Transfected Transactivation In Vitro Assays to Detect Estrogen Receptor Agonists and Antagonists, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "A collection of performance-based test guidelines and assays for in vitro chemical testing, including estrogen receptor transactivation and skin sensitisation pathways.", "pt-br": "Coletânea de diretrizes de teste baseadas em desempenho e de ensaios para testes químicos in vitro, incluindo a transativação do receptor de estrogênio e as rotas de sensibilização cutânea."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264265295-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('36'::integer, 'oecd-test-no-493-2024-06-25-performance-based-test-guideline-for-human-recombinant-est'::text, '{"en-us": "OECD (2024), Test No. 493: Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2024), Test No. 493: Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This document describes a Performance-Based Test Guideline for human recombinant in vitro assays to detect substances with estrogen receptor binding affinity, intended for screening and prioritisation.", "pt-br": "Este documento descreve uma Diretriz de Teste Baseada em Desempenho para ensaios in vitro com receptor humano recombinante, destinados a detectar substâncias com afinidade de ligação ao receptor de estrogênio, para fins de triagem e priorização."}'::jsonb, '2024-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264242623-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('37'::integer, 'oecd-test-no-456-2025-06-25-h295r-steroidogenesis-assay-oecd-guidelines-for-the-testin'::text, '{"en-us": "OECD (2025), Test No. 456: H295R Steroidogenesis Assay, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2025), Test No. 456: H295R Steroidogenesis Assay, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "The document provides an OECD Test Guideline for an in vitro screen for chemical effects on steroidogenesis using the human H295R cell line to measure production of 17ß-estradiol and testosterone.", "pt-br": "O documento apresenta uma Diretriz de Teste da OCDE para uma triagem in vitro dos efeitos de substâncias químicas sobre a esteroidogênese, usando a linhagem celular humana H295R para medir a produção de 17ß-estradiol e testosterona."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264122642-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('38'::integer, 'oecd-test-no-458-2023-07-04-stably-transfected-human-androgen-receptor-transcriptional'::text, '{"en-us": "OECD (2023), Test No. 458: Stably Transfected Human Androgen Receptor Transcriptional Activation Assay for Detection of Androgenic Agonist and Antagonist Activity of Chemicals, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2023), Test No. 458: Stably Transfected Human Androgen Receptor Transcriptional Activation Assay for Detection of Androgenic Agonist and Antagonist Activity of Chemicals, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This guideline describes in vitro ARTA assays using stably transfected cell lines (AR-EcoScreen, AR-CALUX, 22Rv1/MMTV_GR-KO) to identify androgen receptor agonists and antagonists.", "pt-br": "Esta diretriz descreve ensaios ARTA in vitro com linhagens celulares estavelmente transfectadas (AR-EcoScreen, AR-CALUX, 22Rv1/MMTV_GR-KO) para identificar agonistas e antagonistas do receptor de andrógeno."}'::jsonb, '2023-07-04'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264366-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('42'::integer, 'oecd-test-no-496-2026-07-02-in-vitro-macromolecular-test-method-for-identifying-chemic'::text, '{"en-us": "OECD (2026), Test No. 496: In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2026), Test No. 496: In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "OECD Test Guideline 496 describes an in vitro biochemical test method using a macromolecular matrix to identify chemicals inducing serious eye damage or those not requiring classification for eye irritation or serious eye damage.", "pt-br": "A Diretriz de Teste 496 da OCDE descreve um método de teste bioquímico in vitro que usa uma matriz macromolecular para identificar substâncias químicas que induzem lesões oculares graves ou que não requerem classificação para irritação ocular ou lesões oculares graves."}'::jsonb, '2026-07-02'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/970e5cd9-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('43'::integer, 'oecd-test-no-495-2019-06-18-ros-reactive-oxygen-species-assay-for-photoreactivity-oecd'::text, '{"en-us": "OECD (2019), Test No. 495: Ros(Reactive Oxygen Species) Assay for Photoreactivity, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,", "pt-br": "OECD (2019), Test No. 495: Ros(Reactive Oxygen Species) Assay for Photoreactivity, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "A collection of OECD Test Guidelines for the testing of chemicals, including methods for assessing phototoxicity, immunotoxicity, and cytochrome P450 induction.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, incluindo métodos para avaliar fototoxicidade, imunotoxicidade e indução do citocromo P450."}'::jsonb, '2019-06-18'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/915e00ac-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('44'::integer, 'oecd-test-no-212-1998-09-21-fish-short-term-toxicity-test-on-embryo-and-sac-fry-stages'::text, '{"en-us": "OECD (1998), Test No. 212: Fish, Short-term Toxicity Test on Embryo and Sac-Fry Stages, OECD Guidelines for the Testing of Chemicals, Section 2, OECD Publishing, Paris,", "pt-br": "OECD (1998), Test No. 212: Fish, Short-term Toxicity Test on Embryo and Sac-Fry Stages, OECD Guidelines for the Testing of Chemicals, Section 2, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "OECD guideline for testing chemicals describing a short-term toxicity test on fish embryo and sac-fry stages to determine lethal and sub-lethal effects of substances dissolved in water.", "pt-br": "Diretriz da OCDE para a avaliação de substâncias químicas que descreve um teste de toxicidade de curto prazo em estágios de embrião e alevino de peixe, para determinar efeitos letais e subletais de substâncias dissolvidas na água."}'::jsonb, '1998-09-21'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264070141-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('45'::integer, 'oecd-test-no-236-2025-06-25-fish-embryo-acute-toxicity-fet-test-oecd-guidelines-for-th'::text, '{"en-us": "OECD (2025), Test No. 236: Fish Embryo Acute Toxicity(FET) Test, OECD Guidelines for the Testing of Chemicals, Section 2, OECD Publishing, Paris,", "pt-br": "OECD (2025), Test No. 236: Fish Embryo Acute Toxicity(FET) Test, OECD Guidelines for the Testing of Chemicals, Section 2, OECD Publishing, Paris,"}'::jsonb, '{"en-us": "Collection of OECD Test Guidelines for the testing of chemicals, including specific protocols for fish, algae, earthworms, and bumblebees.", "pt-br": "Coletânea de Diretrizes de Teste da OCDE para a avaliação de substâncias químicas, incluindo protocolos específicos para peixes, algas, minhocas e mamangavas (Bombus)."}'::jsonb, '2025-06-25'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264203709-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('46'::integer, 'oecd-test-no-319a-2018-06-27-determination-of-in-vitro-intrinsic-clearance-using-cryop'::text, '{"en-us": "OECD (2018), Test No. 319A: Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP), OECD Guidelines for the Testing of Chemicals, Section 3, OECD Publishing, Paris", "pt-br": "OECD (2018), Test No. 319A: Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP), OECD Guidelines for the Testing of Chemicals, Section 3, OECD Publishing, Paris"}'::jsonb, '{"en-us": "Describes the use of cryopreserved rainbow trout hepatocytes as a metabolising system to determine the in vitro intrinsic clearance of a test chemical.", "pt-br": "Descreve o uso de hepatócitos criopreservados de truta-arco-íris como sistema metabolizante para determinar o clearance intrínseco in vitro de uma substância química de teste."}'::jsonb, '2018-06-27'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264303218-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('47'::integer, 'oecd-test-no-319b-2018-06-27-determination-of-in-vitro-intrinsic-clearance-using-rainb'::text, '{"en-us": "OECD (2018), Test No. 319B: Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9), OECD Guidelines for the Testing of Chemicals, Section 3, OECD Publishing, Paris", "pt-br": "OECD (2018), Test No. 319B: Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9), OECD Guidelines for the Testing of Chemicals, Section 3, OECD Publishing, Paris"}'::jsonb, '{"en-us": "This test guideline describes using rainbow trout liver S9 sub-cellular fraction as a metabolising system to determine the in vitro intrinsic clearance of a test chemical, intended to improve in silico predictions of bioaccumulation in fish.", "pt-br": "Esta diretriz de teste descreve o uso da fração subcelular S9 de fígado de truta-arco-íris como sistema metabolizante para determinar o clearance intrínseco in vitro de uma substância química de teste, com o objetivo de melhorar as previsões in silico de bioacumulação em peixes."}'::jsonb, '2018-06-27'::date, '["method_protocol", "regulation"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264303232-en'::text, '{}'::integer[]);
INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url", "internal_doc_refs") VALUES ('48'::integer, 'oecd-test-no-421-2025-06-25-reproduction-developmental-toxicity-screening-test-oecd-gu'::text, '{"en-us": "OECD (2025), Test No. 421: Reproduction/Developmental Toxicity Screening Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris", "pt-br": "OECD (2025), Test No. 421: Reproduction/Developmental Toxicity Screening Test, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris"}'::jsonb, '{"en-us": "An OECD Test Guideline for screening the effects of chemicals on male and female reproductive performance, updated to include endocrine disruptor endpoints like anogenital distance, nipple retention, and thyroid examination in rats.", "pt-br": "Diretriz de Teste da OCDE para a triagem dos efeitos de substâncias químicas sobre o desempenho reprodutivo de machos e fêmeas, atualizada para incluir desfechos de desreguladores endócrinos, como a distância anogenital, a retenção de mamilos e o exame da tireoide em ratos."}'::jsonb, '2025-06-25'::date, '["regulation", "method_protocol"]'::jsonb, '{"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}'::jsonb, 'https://doi.org/10.1787/9789264264380-en'::text, '{}'::integer[]);
