INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('79'::integer, '1'::integer, 'matrix'::text, '{"en-us": "Dermal substitute of the EpiSkin model: collagen type I matrix coated with collagen type IV", "pt-br": "Substituto dérmico do modelo EpiSkin: matriz de colágeno tipo I revestida com colágeno tipo IV"}'::jsonb, NULL, NULL, NULL, 'DB-ALM protocol 131 (EpiSkin-SM); species and origin of the collagen are not stated'::text, '2026-10-24 11:23:45.308781+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('24'::integer, '11'::integer, 'reconstructed_tissue'::text, '{"en-us": "Reconstructed human epidermis models: LabCyte EPI-MODEL24 (EpiSensA) and EpiDerm EPI-200 (Epi2SensA)", "pt-br": "Modelos de epiderme humana reconstruída: LabCyte EPI-MODEL24 (EpiSensA) e EpiDerm EPI-200 (Epi2SensA)"}'::jsonb, '1'::integer, 'human'::text, NULL, 'TG 442D text; EpiSensA SOP v2.6 (Kao): LabCyte EPI-MODEL24 (J-TEC kit 401124) reconstructed from normal human epidermal keratinocytes, ready-to-use assay medium in the kit (composition not given in the SOP); LabCyte manual: model made by culturing normal human epidermal cells'::text, '2026-10-23 21:05:41.09138+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('80'::integer, '1'::integer, 'biological_extract'::text, '{"en-us": "Irradiated 3T3-J2 feeder cells used to expand the keratinocytes of the LabCyte EPI-MODEL24", "pt-br": "Células alimentadoras 3T3-J2 irradiadas usadas para expandir os queratinócitos do LabCyte EPI-MODEL24"}'::jsonb, '3'::integer, NULL, 'true'::boolean, 'JaCVAM/J-TEC SOP v8.3 and SCT peer review report: keratinocytes (neonate foreskin) cultured with 3T3-J2 cells as a feeder layer; species not stated in the documents (3T3-J2 is a mouse fibroblast line, to be confirmed)'::text, '2026-10-24 11:55:43.011519+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('81'::integer, '11'::integer, 'biological_extract'::text, '{"en-us": "Irradiated 3T3-J2 feeder cells used to expand the keratinocytes of the LabCyte EPI-MODEL24 (EpiSensA)", "pt-br": "Células alimentadoras 3T3-J2 irradiadas usadas para expandir os queratinócitos do LabCyte EPI-MODEL24 (EpiSensA)"}'::jsonb, '3'::integer, NULL, 'true'::boolean, 'JaCVAM/J-TEC SOPs of the same model; species not stated in the documents (3T3-J2 is a mouse fibroblast line, to be confirmed)'::text, '2026-10-24 11:55:43.011519+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('84'::integer, '9'::integer, 'biological_extract'::text, '{"en-us": "Irradiated 3T3-J2 feeder cells used to expand the corneal epithelial cells of the LabCyte CORNEA-MODEL24", "pt-br": "Células alimentadoras 3T3-J2 irradiadas usadas para expandir as células epiteliais da córnea do LabCyte CORNEA-MODEL24"}'::jsonb, '3'::integer, NULL, 'true'::boolean, 'JaCVAM/J-TEC protocol v2.7: normal human corneal epithelial cells from a donor cornea cultured with 3T3-J2 cells as a feeder layer; species not stated in the document (3T3-J2 is a mouse fibroblast line, to be confirmed)'::text, '2026-10-24 11:55:43.011519+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('3'::integer, '9'::integer, 'reconstructed_tissue'::text, '{"en-us": "Reconstructed human cornea-like epithelium (RhCE)", "pt-br": "Epitélio corneano humano reconstruído (RhCE)"}'::jsonb, '1'::integer, 'human'::text, NULL, 'TG 492 text; EpiOcular (DB-ALM 164): normal human foreskin-derived epidermal keratinocytes, not transformed, "specialized medium" without composition or serum mention; SkinEthic HCE (DB-ALM 190/191): transformed human corneal epithelial cell line in a chemically defined medium, no serum mentioned; MCTT HCE (Biosolution MM331 sheet, SOP v1.8, protocol v1.7): normal human corneal epithelial cells derived from normal human cornea tissue, 14-day culture in Millicell inserts, shipped on agarose gel with assay medium; medium composition not described and no serum or animal-derived component mentioned; EpiOcular (MatTek product page): NHEK from a single neonatal-foreskin donor, medium DMEM with EGF, insulin, hydrocortisone and proprietary stimulators, "Serum: None", gentamicin and amphotericin B added'::text, '2026-10-23 20:36:05.614375+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('78'::integer, '1'::integer, 'culture_supplement'::text, '{"en-us": "5% fetal bovine serum in the production medium of the LabCyte EPI-MODEL24 SIT (one of the models listed in TG 439); other models may use chemically defined media", "pt-br": "Soro fetal bovino a 5% no meio de produção do LabCyte EPI-MODEL24 SIT (um dos modelos citados na TG 439); outros modelos podem usar meios quimicamente definidos"}'::jsonb, '7'::integer, 'animal'::text, 'true'::boolean, 'JaCVAM/J-TEC SOP v8.3 (SIT): tissue cultured for 13 days at the air-liquid interface in an optimized medium containing 5% fetal bovine serum; SkinEthic RHE (DB-ALM 135): chemically defined growth medium'::text, '2026-10-24 04:07:41.292116+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('1'::integer, '1'::integer, 'reconstructed_tissue'::text, '{"en-us": "Reconstructed human epidermis (RhE) models (TG 439 lists EpiDerm SIT, EpiSkin, SkinEthic RHE, LabCyte EPI-MODEL24 SIT, epiCS, Skin+ and KeraSkin)", "pt-br": "Modelos de epiderme humana reconstruída (RhE) (a TG 439 cita EpiDerm SIT, EpiSkin, SkinEthic RHE, LabCyte EPI-MODEL24 SIT, epiCS, Skin+ e KeraSkin)"}'::jsonb, '1'::integer, 'human'::text, NULL, 'TG 439 text; SkinEthic RHE (DB-ALM 135): normal human keratinocytes on a polycarbonate filter, chemically defined growth medium, no serum mentioned; EpiSkin-SM (DB-ALM 131): human keratinocytes from healthy volunteer donors, kit media composition not given; epiCS (TSAR): model description only; KeraSkin (KoCVAM SOP of the phototoxicity assay v1.3): primary cultured human keratinocytes of Korean origin on Millicell inserts, shipped on agarose gel with the assay medium; medium composition not described and no serum mentioned'::text, '2026-10-23 20:36:05.614375+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('86'::integer, '9'::integer, 'culture_supplement'::text, '{"en-us": "EpiOcular culture medium: DMEM with epidermal growth factor, insulin, hydrocortisone and proprietary stimulators; serum-free (species of insulin and growth factor not stated)", "pt-br": "Meio de cultura do EpiOcular: DMEM com fator de crescimento epidérmico, insulina, hidrocortisona e estimuladores proprietários; sem soro (espécie da insulina e do fator de crescimento não informada)"}'::jsonb, NULL, NULL, NULL, 'MatTek EpiOcular product page (tech specs): "Serum: None"; antibiotics gentamicin 5 ug/ml and amphotericin B 0.25 ug/ml; proprietary stimulators of non-keratinizing epithelial differentiation are not described'::text, '2026-10-24 12:23:37.710661+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('70'::integer, '11'::integer, 'culture_supplement'::text, '{"en-us": "Serum in the KeratinoSens culture medium (type of serum to be agreed with the authority; xeno-free adaptation with human serum available); α-Sens and Epi2SensA are serum/FBS free", "pt-br": "Soro no meio de cultura do KeratinoSens (tipo de soro a combinar com a autoridade; há adaptação sem material animal com soro humano); α-Sens e Epi2SensA não usam soro"}'::jsonb, NULL, 'animal'::text, 'true'::boolean, 'TG 442D text; serum species not stated'::text, '2026-10-23 21:33:49.336062+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('72'::integer, '30'::integer, 'antibody'::text, '{"en-us": "FITC-labelled polyclonal or monoclonal anti-rabies antibody conjugate", "pt-br": "Conjugado de anticorpo anti-rábico policlonal ou monoclonal marcado com FITC"}'::jsonb, NULL, 'animal'::text, 'true'::boolean, 'WOAH 3.1.19; polyclonal antibodies come from immunised animals, monoclonal ones from hybridomas'::text, '2026-10-23 21:47:28.463551+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('73'::integer, '33'::integer, 'antibody'::text, '{"en-us": "Biotinylated anti-nucleoprotein poly- or monoclonal antibodies (streptavidin-peroxidase detection)", "pt-br": "Anticorpos poli- ou monoclonais anti-nucleoproteína biotinilados (detecção com estreptavidina-peroxidase)"}'::jsonb, NULL, 'animal'::text, 'true'::boolean, 'WOAH 3.1.19; polyclonal antibodies come from immunised animals, monoclonal ones from hybridomas'::text, '2026-10-23 21:47:28.463551+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('77'::integer, '11'::integer, 'culture_supplement'::text, '{"en-us": "Serum in the LabCyte EPI-MODEL24 kit used for EpiSensA (5% fetal bovine serum in the production medium; the kit assay medium contains serum); Epi2SensA uses a serum-free assay medium", "pt-br": "Soro no kit LabCyte EPI-MODEL24 usado no EpiSensA (soro fetal bovino a 5% no meio de produção; o meio de ensaio do kit contém soro); o Epi2SensA usa meio de ensaio sem soro"}'::jsonb, '7'::integer, 'animal'::text, 'true'::boolean, 'LabCyte manual (J-TEC, 2017): assay medium contains serum; JaCVAM SOPs of the same model: production medium with 5% fetal bovine serum. TG 442D: Epi2SensA uses serum-free Assay Medium EPI-100-NMM'::text, '2026-10-24 03:38:25.075884+00'::timestamp with time zone);
INSERT INTO public."method_materials" ("id", "method_id", "kind", "name", "species_id", "origin", "animal_derived", "notes", "created_at") VALUES ('82'::integer, '9'::integer, 'culture_supplement'::text, '{"en-us": "5% fetal bovine serum in the production medium of the LabCyte CORNEA-MODEL24 (one of the models listed in the Guideline); EpiOcular and SkinEthic HCE protocols mention no serum", "pt-br": "Soro fetal bovino a 5% no meio de produção do LabCyte CORNEA-MODEL24 (um dos modelos citados na Diretriz); os protocolos do EpiOcular e do SkinEthic HCE não citam soro"}'::jsonb, '7'::integer, 'animal'::text, 'true'::boolean, 'JaCVAM/J-TEC protocol v2.7 (2018): cultured for 13 days at the air-liquid interface in an optimized medium containing 5% fetal bovine serum'::text, '2026-10-24 11:55:43.011519+00'::timestamp with time zone);
INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('20'::integer, 'farmacopeia-MG5.5.2.7.1-00-teste-de-ativacao-de-monocitos-mat'::text, 'true'::boolean, '{"en-us": "Monocyte-activation test", "pt-br": "Teste de Ativação de Monócitos (MAT)"}'::jsonb, '{"en-us": "An in vitro method for the detection of bacterial endotoxins and non-endotoxin pyrogens (NEPs) in parenteral products, using human monocytes or monocytic cell lines to measure the release of pro-inflammatory cytokines.", "pt-br": "Método in vitro para a detecção de endotoxinas bacterianas e pirogênios não-endotoxina (NEPs) em produtos parenterais, utilizando monócitos humanos ou linhagens celulares monocíticas para medir a liberação de citocinas pró-inflamatórias."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, NULL, '{"en-us": "5.5.2.7.1 MONOCYTE ACTIVATION TEST. Farmacopeia Brasileira, 7th edition: volume I - RDC version no 940/2024. MG5.5.2.7.1-00.", "pt-br": "5.5.2.7.1 TESTE DE ATIVAÇÃO DE MONÓCITOS. Farmacopeia Brasileira, 7ª edição: volume I - versão RDC nº 940/2024. MG5.5.2.7.1-00."}'::text, '1'::integer, 'FARMACOPEIA_BR'::text, 'validated'::text, NULL, '{"en-us": "Total replacement. Recommended in preference to the rabbit pyrogen test to reduce the use of animals.", "pt-br": "Substituição total. Recomenda-se a sua utilização, em detrimento do teste de pirogênios em coelhos visando à redução de uso de animais."}'::jsonb, NULL, NULL, '{"en-us": ["MAT", "pyrogen", "endotoxin", "parenteral products", "cytokines"], "pt-br": ["MAT", "pirogênio", "endotoxina", "produtos parenterais", "citocinas"]}'::jsonb, 'Brazilian Pharmacopoeia: Monocyte-activation test. An in vitro method for the detection of bacterial endotoxins and non-endotoxin pyrogens (NEPs) in parenteral products, using human monocytes or monocytic cell lines to measure the release of pro-inflammatory cytokines.'::text, '[-0.022155072540044785, -0.048538267612457275, 0.05053452402353287, -0.018693720921874046, -0.003974349703639746, 0.022009583190083504, -0.024613410234451294, 0.2024725079536438, 0.04083407670259476, 0.06759056448936462, 0.0017837982159107924, -0.0781218409538269, -0.001073712483048439, 0.1573936492204666, -0.07733575254678726, -0.006977482698857784, 0.038421984761953354, -0.021988222375512123, 0.050868693739175797, 0.01600254699587822, 0.04191146418452263, -0.0220529492944479, -0.04740304499864578, -0.0031440206803381443, -0.029070762917399406, 0.040146440267562866, 0.0023570589255541563, -0.011253802105784416, -0.026979153975844383, 0.07195762544870377, 0.0357520766556263, 0.02014816366136074, 0.07291875034570694, -0.03859461471438408, 0.018359582871198654, 0.05562596395611763, -0.03179141879081726, 0.011995959095656872, 0.07838539779186249, -0.013719202019274235, 0.03396153450012207, -0.07635633647441864, -0.0356723889708519, -0.03058774210512638, 0.0671456903219223, -0.004269123077392578, 0.03638710081577301, 0.02758454903960228, 0.03962002322077751, 0.001576982089318335, 0.06444592028856277, 0.029167810454964638, 0.03128000721335411, 0.08250938355922699, 0.015429260209202766, -0.05203067511320114, 0.02235565334558487, -0.1036878228187561, -0.00933857075870037, 0.05788031965494156, -0.07867351174354553, -0.005866378545761108, -0.032776035368442535, 0.030364064499735832, 0.030910132452845573, 0.021502560004591942, 0.005715761799365282, 0.02411152608692646, -0.021380355581641197, -0.025880003347992897, -0.05757870152592659, -0.03031153231859207, 0.036369338631629944, 0.010931361466646194, -0.03553758189082146, 0.07990525662899017, -0.03092174045741558, -0.046720