INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('23'::integer, 'oecd-tg420-fixed-dose-procedure'::text, 'true'::boolean, '{"en-us": "Acute Oral Toxicity - Fixed Dose Procedure", "pt-br": "TG 420 - Toxicidade Aguda Oral – Procedimento de Doses Fixas"}'::jsonb, '{"en-us": "The Fixed Dose Procedure is a method for the assessment of acute oral toxicity in rats, using a stepwise approach to identify doses that produce signs of toxicity without requiring the use of lethal doses as a primary endpoint.", "pt-br": "O Procedimento de Dose Fixa é um método para a avaliação da toxicidade oral aguda em ratos, utilizando uma abordagem gradual para identificar doses que produzem sinais de toxicidade sem exigir o uso de doses letais como endpoint primário."}'::jsonb, 'live_animals'::text, '["in_vivo"]'::jsonb, 'TG 420'::text, NULL, '12'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "The method uses a stepwise procedure with fixed doses, avoids death as an endpoint and uses fewer animals than the traditional methods.", "pt-br": "O método utiliza um procedimento gradual com doses fixas, evita a morte como desfecho e usa menos animais do que os métodos tradicionais."}'::jsonb, '{"en-us": "The method is designed to avoid severe toxic effects or mortality by using doses expected to produce signs of toxicity without death.", "pt-br": "O método foi projetado para evitar efeitos tóxicos graves ou mortalidade, utilizando doses esperadas para produzir sinais de toxicidade sem morte."}'::jsonb, '{"en-us": ["acute oral toxicity", "fixed dose procedure", "rat", "gavage"], "pt-br": ["toxicidade oral aguda", "procedimento de dose fixa", "rato", "gavagem"]}'::jsonb, 'OECD TG 420: Acute Oral Toxicity - Fixed Dose Procedure. The Fixed Dose Procedure is a method for the assessment of acute oral toxicity in rats, using a stepwise approach to identify doses that produce signs of toxicity without requiring the use of lethal doses as a primary endpoint.'::text, '[0.01760261505842209, 0.02164393477141857, 0.026390552520751953, -0.0307078305631876, -0.08439943194389343, -0.0465618371963501, 0.031399134546518326, 0.1549086719751358, 0.025284623727202415, 0.028214361518621445, 0.01320733968168497, 0.029448868706822395, -0.08339028060436249, 0.036319512873888016, -0.09780927747488022, -0.017172038555145264, 0.07925472408533096, 0.035772837698459625, 0.028801167383790016, -0.017782358452677727, 0.0033779877703636885, 0.13944490253925323, 0.0523546040058136, 0.0036256429739296436, -0.05893988907337189, -0.016525274142622948, -0.0728536918759346, -0.016232676804065704, 0.09047850221395493, 0.0389634408056736, 0.059206824749708176, 0.1235114112496376, -0.008841934613883495, -0.06732583791017532, -0.059328559786081314, -0.0011530506890267134, -0.07626526802778244, 0.02054021507501602, -0.021081887185573578, 0.03767532482743263, 0.023925654590129852, -0.04150121286511421, -0.04477843642234802, 0.07665432244539261, 0.037207480520009995, -0.04580226540565491, -0.07094065099954605, -0.025256777182221413, -0.038389235734939575, 0.07232067734003067, 0.08022405207157135, -0.016360271722078323, -0.010174487717449665, -0.0203073900192976, -0.043659087270498276, -0.06972936540842056, 0.047519247978925705, -0.0376565083861351, -0.04421081393957138, 0.07965294271707535, -0.03771049529314041, -0.004877835046499968, 0.02471492998301983, 0.05823909491300583, 0.1234516054391861, 0.03583478182554245, 0.04665915668010712, -0.05952001363039017, -0.04920300841331482, -0.007958216592669487, -0.015870703384280205, -0.06806318461894989, 0.025729216635227203, -0.0