INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('8'::integer, 'oecd-tg460-fluorescein-leakage'::text, 'true'::boolean, '{"en-us": "Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants", "pt-br": "TG 460 - Teste de Permeação de Fluoresceína"}'::jsonb, '{"en-us": "An in vitro assay using a confluent monolayer of Madin-Darby Canine Kidney (MDCK) cells as a barrier to identify water-soluble ocular corrosives and severe irritants (UN GHS Category 1) by measuring increased fluorescein permeability resulting from impaired cell junctions.", "pt-br": "Um ensaio in vitro que utiliza uma monocamada confluente de células Madin-Darby Canine Kidney (MDCK) como barreira para identificar corrosivos oculares e irritantes graves (UN GHS Categoria 1), solúveis em água, medindo o aumento da permeabilidade à fluoresceína resultante do comprometimento das junções celulares."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 460'::text, NULL, '29'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The method is used for identifying ocular corrosives and severe irritants as part of a tiered testing strategy, providing an alternative to animal testing.", "pt-br": "Substituição parcial. O método é utilizado para identificar corrosivos oculares e irritantes graves como parte de uma estratégia de teste em níveis, oferecendo uma alternativa ao teste em animais."}'::jsonb, NULL, NULL, '{"en-us": ["fluorescein leakage", "ocular corrosion", "ocular irritation", "MDCK cells", "in vitro"], "pt-br": ["vazamento de fluoresceína", "corrosão ocular", "irritação ocular", "células MDCK", "in vitro"]}'::jsonb, 'OECD TG 460: Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants. An in vitro assay using a confluent monolayer of Madin-Darby Canine Kidney (MDCK) cells as a barrier to identify water-soluble ocular corrosives and severe irritants (UN GHS Category 1) by measuring increased fluorescein permeability resulting from impaired cell junctions.'::text, '[-0.05790990591049194, -0.10462048649787903, 0.08116541802883148, -0.013621948659420013, 0.04362299293279648, -0.0762161985039711, 0.06978844106197357, 0.11765862256288528, 0.00021734082838520408, 0.060427017509937286, -0.050506021827459335, -0.02346624806523323, -0.028015946969389915, 0.13219134509563446, -0.1456352174282074, -0.007645352277904749, -0.0653582289814949, -0.029987534508109093, 0.008471683599054813, -0.03318144381046295, 0.05752892419695854, 0.014941983856260777, -0.0495707131922245, -0.01562570407986641, 0.004225765820592642, -0.045753929764032364, 0.06423193216323853, -0.017025278881192207, -0.05703843757510185, -0.017122134566307068, -0.06280983984470367, 0.02384153939783573, -0.13622532784938812, 0.004578832071274519, -0.029354045167565346, 0.00016868299280758947, -0.016005318611860275, -0.04059617593884468, -0.03854304552078247, -0.009287473745644093, 0.0038054445758461952, 0.01645847037434578, -0.04219122231006622, -0.004292795900255442, 0.08779902756214142, -0.0045260353945195675, 0.02783975750207901, -0.052355777472257614, -0.004075269680470228, 0.09911125898361206, -0.05990980938076973, 0.010193025693297386, -0.015071002766489983, -0.04884948208928108, -0.028058569878339767, 0.0009506097412668169, -0.0563935860991478, -0.06268659234046936, -0.0032518969383090734, 0.0975811630487442, -0.008608032017946243, -0.090472012758255, 0.06853324919939041, -0.010534062050282955, 0.0028099685441702604, -0.004424110054969788, 0.013304449617862701, -0.013658380135893822, 0.00