INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('37'::integer, 'oecd-tg422-combined-repeated-dose-reproduction-developmental-toxicity-screening'::text, 'true'::boolean, '{"en-us": "Combined Repeated Dose Toxicity Study with the Reproduction/Developmental Toxicity Screening Test", "pt-br": "TG 422 - Estudo de toxicidade repetida combinado com teste de toxicidade reprodutiva"}'::jsonb, '{"en-us": "A screening test guideline designed to assess the effects of a test chemical on male and female reproductive performance, developmental toxicity, and general repeated dose toxicity in rats, including endocrine disruptor endpoints.", "pt-br": "Uma diretriz de teste de triagem projetada para avaliar os efeitos de uma substância química de teste no desempenho reprodutivo de machos e fêmeas, toxicidade no desenvolvimento e toxicidade geral por doses repetidas em ratos, incluindo endpoints de desregulação endócrina."}'::jsonb, 'live_animals'::text, '["in_vivo"]'::jsonb, 'TG 422'::text, NULL, '49'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "Reduces the total number of animals required compared to conducting separate experiments for repeated dose and reproductive/developmental toxicity.", "pt-br": "Reduz o número total de animais necessários em comparação com a realização de ensaios separados de toxicidade por doses repetidas e toxicidade reprodutiva ou do desenvolvimento."}'::jsonb, NULL, '{"en-us": ["reproductive toxicity", "developmental toxicity", "repeated dose toxicity", "endocrine disruption", "rat"], "pt-br": ["toxicidade reprodutiva", 