INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('47'::integer, 'oecd-tg494-vitrigel-eye-irritancy-test'::text, 'true'::boolean, '{"en-us": "Vitrigel - Eye Irritancy Test Method", "pt-br": "TG 494 - Vitrigel - Teste de irritação ocular para identificação de substâncias químicas que não requerem classificação e rotulagem para irritação ocular ou sério dano ocular"}'::jsonb, '{"en-us": "An in vitro test method using human corneal epithelium (hCE) models to identify chemicals not requiring classification and labelling for eye irritation or serious eye damage by measuring changes in Transepithelial Electrical Resistance (TEER) values.", "pt-br": "Um método de teste in vitro utilizando modelos de epitélio corneano humano (hCE) para identificar produtos químicos que não requerem classificação e rotulagem para irritação ocular ou danos oculares graves, medindo alterações nos valores de Resistência Elétrica Transepitelial (TEER)."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 494'::text, NULL, '41'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. Allows the identification of chemicals not requiring classification and labelling for eye irritation or serious eye damage without the use of animal testing.", "pt-br": "Substituição parcial. Permite a identificação de produtos químicos que não requerem classificação e rotulagem para irritação ocular ou danos oculares graves sem o uso de testes em animais."}'::jsonb, NULL, NULL, '{"en-us": ["Vitrigel", "eye irritation", "TEER", "human corneal epithelium", "hCE"]