INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('33'::integer, 'rabies-direct-rapid-immunohistochemistry-test'::text, 'true'::boolean, '{"en-us": "Direct rapid immunohistochemistry test (dRIT)", "pt-br": "Teste Rápido de Imuno-histoquímica Direta (Direct Rapid Immunohistochemistry Test) - dRIT"}'::jsonb, '{"en-us": "A diagnostic method for rabies using streptavidin–biotin peroxidase staining to detect lyssavirus antigens in touch impressions of CNS tissues. It is an alternative to the direct fluorescent antibody (DFA) test that does not require a fluorescence microscope.", "pt-br": "Método para diagnóstico da raiva que detecta antígenos de lisavírus em impressões de tecidos do sistema nervoso central por coloração com peroxidase baseada em estreptavidina-biotina. Pode ser realizado sem microscópio de fluorescência, diferentemente do teste de imunofluorescência direta (DFA)."}'::jsonb, 'slaughterhouse_byproduct'::text, '["in_vitro"]'::jsonb, NULL, 'World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729'::text, '50'::integer, 'WOAH Terrestrial Manual 2025'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The dRIT is an alternative to the direct fluorescent antibody (DFA) test for rabies diagnosis and does not require fluorescence microscopy. For suitable samples, diagnosis can be performed without mouse inoculation.", "pt-br": "Substituição parcial. O dRIT é uma alternativa ao teste de imunofluorescência direta (DFA) para o diagnóstico da raiva e dispensa microscopia de fluorescência. Para amostras adequadas, o diagnóstico pode ser realizado sem inoculação em camundongos."}'::jsonb, NULL, NULL, '{"en-us": ["rabies", "lyssavirus", "immunohistochemistry", "dRIT", "diagnosis"], "pt-br": ["raiva", "lyssavirus", "imuno-histoquímica", "dRIT", "diagnóstico"]}'::jsonb, 'WOAH Terrestrial Manual 2025: Direct rapid immunohistochemistry test (dRIT). A diagnostic method for rabies using streptavidin-biotin peroxidase staining to detect lyssavirus antigens in touch impressions of CNS tissues. It is an alternative to the direct fluorescent antibody (DFA) test that does not require a fluorescence microscope.'::text, '[-0.04195915162563324, 0.02297287806868553, -0.04496696591377258, -0.02636677958071232, 0.06533675640821457, -0.08752702921628952, -0.017333248630166054, 0.07724703103303909, -0.05943915992975235, 0.06170498579740524, -0.057549431920051575, -0.06418804079294205, -0.026049960404634476, 0.0884491354227066, -0.15055572986602783, -0.03979135677218437, -0.05475292727351189, 0.03708891198039055, 0.03651681914925575, 0.0560138039290905, -0.055151913315057755, 0.0721772089600563, 0.00017429859144613147, -0.08333268761634827, -0.011587964370846748, 0.04537061229348183, 0.024511467665433884, 0.033098023384809494, 0.01452868152409792, -0.010332554578781128, 0.042319405823946, 0.01273281592875719, -0.03187240660190582, 0.024791285395622253, -0.02466968633234501, 0.009085469879209995, -0.005026842933148146, -0.021044177934527397, 0.008679885417222977, 0.01972072944045067, 0.04634619131684303, -0.022534368559718132, 0.08576931804418564, -0.013409643433988094, 0.017908107489347458, -0.009961653500795364, -0.0893615186214447, 0.09608855843544006, 0.008536150678992271, -0.1287418156862259, 0.0770670622587204, -0.02096930891275406, 0.004784740507602692, 0.0926738828420639, -0.0608125738799572, -0.05580822750926018, -0.026730500161647797