INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('11'::integer, 'oecd-tg442d-in-vitro-skin-sensitisation'::text, 'true'::boolean, '{"en-us": "In Vitro Skin Sensitisation: Key Event on Keratinocyte Activation", "pt-br": "TG 442D - Sensibilização cutânea in vitro: Evento-Chave de Ativação de Queratinócitos"}'::jsonb, '{"en-us": "A Key Event based Test Guideline addressing the human health hazard endpoint skin sensitisation, focusing on keratinocyte activation. It includes five in vitro methods: KeratinoSens, LuSens, EpiSensA, Epi2SensA, and α-Sens.", "pt-br": "Uma Diretriz de Teste baseada em Evento-Chave que aborda o endpoint de perigo à saúde humana sensibilização cutânea, com foco na ativação de queratinócitos. Inclui cinco métodos in vitro: KeratinoSens, LuSens, EpiSensA, Epi2SensA e α-Sens."}'::jsonb, 'mixed_or_variable'::text, '["in_vitro"]'::jsonb, 'TG 442D'::text, NULL, '27'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The test methods are used for supporting the discrimination between skin sensitisers and non-sensitisers as an alternative to animal testing.", "pt-br": "Substituição parcial. Os métodos de teste são usados para apoiar a discriminação entre sensibilizantes cutâneos e não sensibilizantes como uma alternativa aos testes em animais."}'::jsonb, NULL, NULL, '{"en-us": ["skin sensitisation", "keratinocyte activation", "AOP", "adverse outcome pathway", "in vitro"], "pt-br": ["sensibilização cutânea", "ativação de queratinócitos", "AOP", "via de desfecho adverso", "in vitro"]}'::jsonb, 'OECD TG 442D: In Vitro Skin Sensitisation: Key Event on Keratinocyte Activation. A Key Event based Test Guideline addressing the human health hazard endpoint skin sensitisation, focusing on keratinocyte activation. It includes five in vitro methods: KeratinoSens, LuSens, EpiSensA, Epi2SensA, and alpha-Sens.'::text, '[0.006323023233562708, 0.0030499265994876623, 0.09156777709722519, -0.007372197229415178, 0.06265326589345932, 0.0019817054271698, 0.09178892523050308, 0.13726554811000824, -0.0530509427189827, 0.046216849237680435, 0.03633735328912735, -0.05453721806406975, -0.06097181513905525, 0.03380453586578369, -0.02161034755408764, 0.03054625168442726, 0.017517611384391785, 0.06465412676334381, 0.002886418020352721, -0.06318075209856033, 0.04718819260597229, -0.052386071532964706, 0.05818057805299759, 0.018497362732887268, -0.06003877893090248, -0.0051867906004190445, 0.024936318397521973, 0.04803583025932312, 0.01120439451187849, -0.03351103514432907, 0.0340917743742466, -0.0460767038166523, -0.03153045102953911, -0.008749122731387615, -0.030240433290600777, -0.027606621384620667, -0.05721849203109741, -0.021492324769496918, -0.014563479460775852, 0.012865452095866203, 0.05156572163105011, -0.09957726299762726, -0.09288789331912994, 0.001724187401123345, 0.12551163136959076, -0.06579696387052536, 0.00839164573699236, 0.010133828967809677, -0.07464899867773056, 0.06789597123861313, 0.04729824513196945, -0.0888228788971901, 0.05098478123545647, -0.0753294825553894, -0.05247338116168976, -0.012636933475732803, -0.09991433471441269, -0.006667521316558123, 0.02770231105387211, 0.01648057997226715, 0.009740583598613739, -0.0871034562587738, 0.017869845032691956, -0.020261742174625397, 0.052354596555233, -0.012006153352558613, 0.0793740376830101, -0.07812362909317017, 0.0017128483159467578, -0.042189061641693115, -0.02982131950557232, -0.03193025663495064, 0.07002042979001999, 0.060550153255462646, 0.004347352776676416, 0.08427692204713821, -0.017266789451241493, -0.02268373779952526, 