INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('12'::integer, 'oecd-tg442e-in-vitro-skin-sensitisation'::text, 'true'::boolean, '{"en-us": "In Vitro Skin Sensitisation: Key Event on Dendritic Cell Activation", "pt-br": "TG 442E - Sensibilização cutânea in vitro: ensaios de sensibilização cutânea in vitro abordando o evento chave na ativação de células dendríticas no Caminho da Resposta Adversa (AOP) para sensibilização cutânea"}'::jsonb, '{"en-us": "In vitro test guideline addressing the activation of dendritic cells within the skin sensitisation Adverse Outcome Pathway (AOP). Methods include h-CLAT, U-SENS, IL-8 Luc assay, and GARDskin, used for discriminating between skin sensitisers and non-sensitisers.", "pt-br": "Diretriz de teste in vitro que aborda a ativação de células dendríticas dentro da via de desfecho adverso (AOP) para sensibilização cutânea. Os métodos incluem h-CLAT, U-SENS, ensaio IL-8 Luc e GARDskin, usados para distinguir entre sensibilizantes e não sensibilizantes cutâneos."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 442E'::text, NULL, '28'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The guideline provides in vitro methods to address skin sensitisation without the use of animals by targeting key events in the AOP.", "pt-br": "Substituição parcial. A diretriz fornece métodos in vitro para abordar a sensibilização cutânea sem o uso de animais, visando eventos-chave na AOP."}'::jsonb, NULL, NULL, '{"en-us": ["skin sensitisation", "dendritic cells", "h-CLAT", "U-SENS", "IL-8 Luc", "GARDskin", "AOP", "Adverse Outcome Pathway"], "pt-br": ["sensibilização cutânea", "células dendríticas", "h-CLAT", "U-SENS", "IL-8 Luc", "GARDskin", "AOP", "Via de Desfecho Adverso"]}'::jsonb, 'OECD TG 442E: In Vitro Skin Sensitisation: Key Event on Dendritic Cell Activation. In vitro test guideline addressing the activation of dendritic cells within the skin sensitisation Adverse Outcome Pathway (AOP). Methods include h-CLAT, U-SENS, IL-8 Luc assay, and GARDskin, used for discriminating between skin sensitisers and non-sensitisers.'::text, '[-0.022357283160090446, 0.007864603772759438, 0.07829391211271286, 0.013368249870836735, 0.07858037948608398, -0.01480188500136137, 0.09567703306674957, 0.13599981367588043, -0.02537616342306137, 0.0069282762706279755, -0.006540665868669748, -0.019627874717116356, -0.026796922087669373, 0.032913465052843094, 0.019515719264745712, 0.04103550314903259, 0.04120967164635658, 0.05233244597911835, 0.04310384392738342, -0.10388815402984619, -0.03844229504466057, 0.06761065870523453, 0.06187901273369789, -0.04347436502575874, -0.05177043005824089, -0.09118414670228958, 0.06410107761621475, 0.04605376347899437, -0.011449798941612244, -0.008537836372852325, 0.023843975737690926, -0.05204906314611435, -0.03948560357093811, 0.021016046404838562, -0.05646314471960068, -0.01003153994679451, -0.06794311106204987, -0.0033470012713223696, 0.02230309508740902, -0.00012112813419662416, 0.05605195090174675, -0.0236645694822073, -0.08631771802902222, -0.012172767892479897, 0.09841248393058777, -0.044816724956035614, -0.03839825838804245, 0.04496532678604126, -0.08276720345020294, 0.1295257806777954, 0.07008732855319977, 0.005148475524038076, 0.030342277139425278, -0.013217044062912464, -0.06604021042585373, 0.012962322682142258, -0.05138661712408066, 0.00040001823799684644, 0.03145625442266464, -0.0017079653916880488, -0.01758798584342003, -0.09861329197883606, 0.06594403088092804, -0.04585983231663704, 0.03499571979045868, -0.0383396893