INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('40'::integer, 'oecd-tg491-short-time-exposure-in-vitro'::text, 'true'::boolean, '{"en-us": "Short Time Exposure In Vitro Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage", "pt-br": "TG 491 - Teste in vitro de curta duração para danos oculares"}'::jsonb, '{"en-us": "A cytotoxicity-based in vitro assay using Statens Seruminstitut Rabbit Cornea (SIRC) cells to identify chemicals inducing serious eye damage or those not requiring classification, based on relative cell viability measured by the MTT assay after a five-minute exposure.", "pt-br": "Um ensaio in vitro baseado em citotoxicidade usando células da córnea de coelho Statens Seruminstitut (SIRC) para identificar produtos químicos que induzem lesão ocular grave ou aqueles que não requerem classificação, com base na viabilidade celular relativa medida pelo ensaio MTT após uma exposição de cinco minutos."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 491'::text, NULL, '34'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The method is designed to identify chemicals inducing serious eye damage or those not requiring classification, allowing for the classification of eye hazard potential without the use of live animals.", "pt-br": "Substituição parcial. O método identifica substâncias que causam lesões oculares graves e substâncias que não requerem classificação quanto ao perigo ocular, permitindo essa avaliação sem o uso de animais vivos."}'::jsonb, NULL, NULL, '{"en-us": ["cytotoxicity", "SIRC cells", "MTT assay", "ocular hazard", "UN GHS Category 1"], "pt-br": ["citotoxicidade", "células SIRC", "ensaio MTT", "perigo ocular", "Categoria 1 GHS"]}'::jsonb, 'OECD TG 491: Short Time Exposure In Vitro Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage. A cytotoxicity-based in vitro assay using Statens Seruminstitut Rabbit Cornea (SIRC) cells to identify chemicals inducing serious eye damage or those not requiring classification, based on relative cell viability measured by the MTT assay after a five-minute exposure.'::text, '[0.02101285383105278, -0.022909095510840416, 0.08213537186384201, 0.0018309729639440775, 0.05820504203438759, -0.023839706555008888, 0.06653845310211182, 0.15534314513206482, -0.047981731593608856, 0.11832338571548462, 0.011301137506961823, -0.01893109641969204, -0.009772391058504581, 0.07196936011314392, -0.13150754570960999, -0.016193659976124763, 0.03442104160785675, -0.0068634022027254105, 0.021151317283511162, -0.028246553614735603, 0.06479962170124054, 0.06109170243144035, 0.04921024292707443, 0.012656282633543015, -0.035166941583156586, -0.03436702489852905, -0.015903301537036896, 0.04599057510495186, 0.01853775419294834, -0.03327260538935661, -0.01803886704146862, 0.051725391298532486, 0.001225315616466105, 0.0233653262257576, -0.038390152156353, -0.059837911278009415, 0.011374962516129017, -0.0227682963013649, -0.016518564894795418, -0.007653788197785616, 0.02007106877863407, -0.11508619785308838, -0.06012461334466934, 0.040698010474443436, 0.06890533119440079, -0.00376089196652174, -0.004434249829500914, -0.014113537967205048, -0.05687308683991432, 0.059504009783267975, -0.018622156232595444, -0.01297023892402649, -0.022899316623806953, -0.02775457687675953, -0.02865488827228546, 0.006200788542628288, -0.0853257104754448, -