INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('22'::integer, 'oecd-gd129-cytotoxicity-starting-dose'::text, 'true'::boolean, '{"en-us": "Basal Cytotoxicity for Acute Toxicity Starting Dose Estimation", "pt-br": "TG 129 - estimativa da dose inicial para teste de toxicidade aguda oral sistêmica"}'::jsonb, '{"en-us": "In vitro basal cytotoxicity assay based on neutral red uptake (NRU), using BALB/c 3T3 cells or normal human keratinocytes (NHK). The IC50 obtained is used to estimate an LD50 and to support the selection of the starting dose in in vivo acute oral toxicity tests, with the potential to reduce the number of animals used.", "pt-br": "Ensaio de citotoxicidade basal in vitro baseado na captação de vermelho neutro (NRU), utilizando células BALB/c 3T3 ou queratinócitos humanos normais (NHK). O IC50 obtido é utilizado para estimar uma LD50 e auxiliar na seleção da dose inicial de testes de toxicidade aguda oral in vivo, com potencial de reduzir o número de animais utilizados."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'GD 129'::text, NULL, '11'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement; total if accepted by the regulatory authority. Depending on the regulatory authority, the in vitro basal cytotoxicity result may also be used as a replacement for in vivo acute oral toxicity testing.", "pt-br": "Substituição parcial; total se aceita pela autoridade regulatória. Dependendo da autoridade regulatória, o resultado de citotoxicidade basal in vitro também pode ser usado como método de substituição ao teste de toxicidade oral aguda in vivo."}'::jsonb, '{"en-us": "By estimating the starting dose for acute oral toxicity tests, the number of animals required to determine the LD50 can be reduced by up to 50% compared to default starting doses.", "pt-br": "Ao estimar a dose inicial para ensaios de toxicidade oral aguda, é possível reduzir em até 50% o número de animais necessários para determinar a DL50, em comparação com doses iniciais padrão."}'::jsonb, NULL, '{"en-us": ["cytotoxicity", "neutral red uptake", "NRU", "acute oral toxicity", "starting dose", "3T3", "NHK"], "pt-br": ["citotoxicidade", "captação de vermelho neutro", "NRU", "toxicidade oral aguda", "dose inicial", "3T3", "NHK"]}'::jsonb, 'OECD GD 129: Basal Cytotoxicity for Acute Toxicity Starting Dose Estimation. In vitro basal cytotoxicity assay based on neutral red uptake (NRU), using BALB/c 3T3 cells or normal human keratinocytes (NHK). The IC50 obtained is used to estimate an LD50 and to support the selection of the starting dose in in vivo acute oral toxicity tests, with the potential to reduce the number of animals used.'::text, '[-0.008190575987100601, -0.019966568797826767, -0.017188522964715958, -0.08307579904794693, -0.02931881695985794, -0.04338023439049721, 0.04979601502418518, 0.17643260955810547, -0.03135169297456741, 0.08736500144004822, -0.015259342268109322, -0.026323677971959114, -0.008997657336294651, 0.028377145528793335, -0.07425548881292343, 0.00029200708377175033, 0.08178450167179108, 0.07280267775058746, 0.0077286530286073685, -0.010416102595627308, -0.03563031926751137, 0.07051574438810349, 0.055938851088285446, 0.02119392529129982, -0.015572047792375088, 0.002221167553216219, -0.016243744641542435, -0.052138954401016235, -0.010440790094435215, 0.00635039247572422, 0.041954442858695984, 0.028399452567100525, 0.0764228031039238, -0.04823917895555496, 0.03221019357442856, -0.06520851701498032, -0.070807084441185, -0.02352280728518963, -0.04311666265130043, 0.023167008534073