INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('10'::integer, 'oecd-tg442c-in-chemico-skin-sensitisation'::text, 'true'::boolean, '{"en-us": "In Chemico Skin Sensitisation", "pt-br": "TG 442C - Sensibilização cutânea in chemico"}'::jsonb, '{"en-us": "This Test Guideline addresses the molecular initiating event of skin sensitisation, namely protein reactivity, by quantifying the reactivity of test chemicals towards model synthetic peptides or amino acid derivatives containing either lysine or cysteine. It includes three methods: DPRA, ADRA, and kDPRA.", "pt-br": "Esta Diretriz de Teste aborda o evento molecular inicial da sensibilização cutânea, nomeadamente a reatividade proteica, quantificando a reatividade de substâncias químicas de teste em relação a peptídeos sintéticos modelo ou derivados de aminoácidos contendo lisina ou cisteína. Inclui três métodos: DPRA, ADRA e kDPRA."}'::jsonb, 'none'::text, '["in_chemico"]'::jsonb, 'TG 442C'::text, NULL, '26'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The test methods provide in chemico alternatives for identifying skin sensitisers without the use of animals.", "pt-br": "Substituição parcial. Os métodos de teste fornecem alternativas in chemico para a identificação de sensibilizantes cutâneos sem o uso de animais."}'::jsonb, NULL, NULL, '{"en-us": ["skin sensitisation", "protein reactivity", "DPRA", "ADRA", "kDPRA", "AOP", "molecular initiating event"], "pt-br": ["sensibilização cutânea", "reatividade proteica", "DPRA", "ADRA", "kDPRA", "AOP", "evento iniciador molecular"]}'::jsonb, 'OECD TG 442C: In Chemico Skin Sensitisation. This Test Guideline addresses the molecular initiating event of skin sensitisation, namely protein reactivity, by quantifying the reactivity of test chemicals towards model synthetic peptides or amino acid derivatives containing either lysine or cysteine. It includes three methods: DPRA, ADRA, and kDPRA.'::text, '[-0.037209369242191315, -0.062372252345085144, 0.014419817365705967, 0.03019428253173828, 0.14567939937114716, 0.005431532859802246, 0.09457455575466156, 0.16396953165531158, -0.006552203558385372, 0.026323409751057625, 0.027020305395126343, -0.05642806366086006, -0.05121185630559921, 0.07477976381778717, -0.021186882629990578, 0.023580463603138924, 0.03220295161008835, 0.03906199336051941, 0.04077458009123802, -0.037012211978435516, -0.009322471916675568, 0.030852263793349266, 0.052209608256816864, 0.000023277973014046438, -0.06951318681240082, -0.05901552364230156, 0.02727295644581318, 0.050709400326013565, -0.015746060758829117, 0.026130974292755127, 0.0314345546066761, -0.027083471417427063, -0.0473518893122673, -0.005613507237285376, 0.03341423720121384, -0.018197152763605118, -0.09056798368692398, -0.0606270357966423, -0.035049039870500565, 0.013826322741806507, 0.025499261915683746, -0.03515904024243355, -0.05851726606488228, -0.025510938838124275, 0.10586631298065186, -0.02556963823735714, 0.019416848197579384, 0.04312389716506004, -0.05827898904681206, 0.04662666097283363, 0.032340239733457565, -0.04642823338508606, -0.020583953708410263, -0.04957744851708412, -0.1400507390499115, 0.010011488571763039, -0.07905749976634979, -0.04114906117320061, 0.0015100371092557907, -0.007987107150256634, -0.014765184372663498, -0.03450659662485123, 0.037578050047159195, -0.012087502516806126, 0.11751225590705872, 0.01214541308581829, 0.09259774535894394, -0.04247036948800087, 0.048497509211301804, -0.08685276657342911, -0.04519928991794586, -0.05323188379406929, 0.06962417811155319, 0.0460346937179565