INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('9'::integer, 'oecd-tg492-rhce-eye-irritation'::text, 'true'::boolean, '{"en-us": "Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage", "pt-br": "TG 492 - Epitélio corneal humano reconstruído (RhCE)"}'::jsonb, '{"en-us": "An in vitro procedure using reconstructed human cornea-like epithelium (RhCE) to identify chemicals that do not require classification and labelling for eye irritation or serious eye damage according to UN GHS, based on the MTT assay to evaluate tissue cytotoxicity.", "pt-br": "Procedimento in vitro utilizando epitélio córneo-símile humano reconstituído (RhCE) para identificar produtos químicos que não requerem classificação e rotulagem para irritação ocular ou dano ocular grave de acordo com o GHS da ONU, baseado no ensaio MTT para avaliar a citotoxicidade tecidual."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 492'::text, NULL, '33'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The RhCE test method serves as a non-animal alternative to evaluate eye hazard potential by mimicking human corneal epithelium properties.", "pt-br": "Substituição parcial. O método de ensaio RhCE serve como uma alternativa não animal para avaliar o potencial de risco ocular ao mimetizar as propriedades do epitélio da córnea humana."}'::jsonb, NULL, NULL, '{"en-us": ["RhCE", "eye irritation", "serious eye damage", "MTT assay", "in vitro", "UN GHS"], "pt-br": ["RhCE", "irritação ocular", "dano ocular grave", "ensaio MTT", "in vitro", "GHS da ONU"]}'::jsonb, 'OECD TG 492: Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage. An in vitro procedure using reconstructed human cornea-like epithelium (RhCE) to identify chemicals that do not require classification and labelling for eye irritation or serious eye damage according to UN GHS, based on the MTT assay to evaluate tissue cytotoxicity.'::text, '[-0.023229850456118584, -0.02238800935447216, -0.004846635740250349, -0.01989409700036049, 0.038405340164899826, -0.024855060502886772, 0.028376994654536247, 0.14432738721370697, -0.054859042167663574, 0.05342690274119377, -0.0021211488638073206, -0.050505414605140686, -0.02645174041390419, 0.058822352439165115, -0.0782642588019371, -0.04196817800402641, 0.009675259701907635, 0.05942070111632347, 0.01486397534608841, -0.09804877638816833, 0.031844962388277054, 0.05808689445257187, 0.04492349550127983, 0.005969305522739887, 0.010382266715168953, -0.03682495281100273, 0.034018564969301224, 0.019480479881167412, -0.005430457182228565, -0.04099461808800697, 0.0019948165863752365, -0.012049881741404533, -0.023231802508234978, -0.02455678954720497, 0.004125188570469618, 0.022191286087036133, -0.06506510823965073, 0.008625201880931854, -0.0036272292491048574, -0.022838415578007698, -0.0249974075704813, -0.10068119317293167, 0.007275172509253025, 0.001763918437063694, 0.05985170975327492, 0.05392424017190933, -0.020239781588315964, 0.012683708220720291, -0.04263969138264656, 0.02745559625327587, 0.02002834714949131, -0.03811157867312431, -0.03197552263736725, 0.029793085530400276, 0.0351417250931263, 0.07085509598255157, -0.08473920822143555, -0.09457802027463913, -0.024488963186740875, 0.02272963337600231, -0.01294137816876173, -0.024768918752670288, 0.0423138365149498, 0.08267423510551453, -0.