INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('49'::integer, 'oecd-tg496-in-vitro-macromolecular-test-method'::text, 'true'::boolean, '{"en-us": "In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage", "pt-br": "TG 496 - Teste macromolecular in vitro para identificação de substâncias químicas que induzem dano ocular severo e substâncias químicas que não requerem classificação para irritação ocular ou dano ocular severo"}'::jsonb, '{"en-us": "A biochemical in vitro test method that uses a macromolecular reagent matrix mimicking the corneal structure. It identifies chemicals inducing serious eye damage and those not requiring classification by measuring protein denaturation and matrix turbidity via light scattering.", "pt-br": "Um método de teste bioquímico in vitro que utiliza uma matriz de reagente macromolecular que mimetiza a estrutura da córnea. Identifica produtos químicos que induzem lesões oculares graves e aqueles que não requerem classificação medindo a desnaturação proteica e a turbidez da matriz por meio de dispersão de luz."}'::jsonb, NULL, '["in_chemico"]'::jsonb, 'TG 496'::text, NULL, '42'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The test method allows for the identification of serious eye damage and classification status in vitro, reducing the reliance on animal testing for eye irritation assessments.", "pt-br": "Substituição parcial. O método de teste permite a identificação de lesões oculares graves e status de classificação in vitro, reduzindo a dependência de testes em animais para avaliações de irritação ocular."}'::jsonb, NULL, NULL, '{"en-us": ["macromolecular reagent", "corneal opacity", "protein denaturation", "eye hazard", "turbidity"], "pt-br": ["reagente macromolecular", "opacidade corneana", "desnaturação proteica", "perigo ocular", "turbidez"]}'::jsonb, 'OECD TG 496: In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage. A biochemical in vitro test method that uses a macromolecular reagent matrix mimicking the corneal structure. It identifies chemicals inducing serious eye damage and those not requiring classification by measuring protein denaturation and matrix turbidity via light scattering.'::text, '[0.023067906498908997, -0.0544021800160408, -0.0008299054461531341, -0.025905316695570946, 0.044317808002233505, -0.018338078632950783, 0.026287440210580826, 0.14825989305973053, -0.04013282060623169, 0.08809493482112885, 0.014591040089726448, -0.059243712574243546, -0.056683897972106934, 0.05614090338349342, -0.09531474858522415, 0.04179518297314644, -0.030458329245448112, 0.06653378903865814, 0.03595311939716339, 0.01745578460395336, 0.1043618842959404, 0.05379583686590195, -0.012425236403942108, 0.009816366247832775, -0.04195569455623627, -0.005775024648755789, 0.05104054883122444, 0.0297046210616827, -0.016390996053814888, -0.04128357395529747, 0.004216576926410198, 0.11180408298969269, -0.03461447358131409, 0.0097585991024971, 0.03920283168554306, -0.019611893221735954, -0.06959379464387894, -0.039844777435064316, -0.030076703056693077, -0.012337946332991123, 0.004991617985069752, -0.053850218653678894, -0.08313771337270737, 0.011139932088553905, 0.10821390151977539, 0.006012645084410906, 0.04962928593158722, 0.021956369280815125, -0.010448354296386242, 0.02639172598719597, -0.050047699362039566, -0.0141