INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('30'::integer, 'rabies-direct-fluorescent-antibody-test'::text, 'true'::boolean, '{"en-us": "Direct fluorescent antibody (DFA) test", "pt-br": "Técnica de Imunofluorescência Direta (Direct Fluorescent Antibody Test) - DFA Test"}'::jsonb, '{"en-us": "Laboratory diagnostic technique used to detect rabies virus antigens in brain tissue impressions or smears, using fluorescein-conjugated anti-rabies antibodies.", "pt-br": "Técnica de diagnóstico laboratorial utilizada para detectar antígenos do vírus da raiva em impressões ou esfregaços de tecido cerebral, por meio de anticorpos anti-rábicos conjugados à fluoresceína."}'::jsonb, 'slaughterhouse_byproduct'::text, '["in_vitro"]'::jsonb, NULL, 'World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729'::text, '50'::integer, 'WOAH Terrestrial Manual 2025'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. Recognized by CONCEA Resolution 75/2026 as an alternative to mouse inoculation for rabies diagnosis; mouse inoculation is allowed only as a last resort when recognized alternatives leave the diagnosis inconclusive.", "pt-br": "Substituição parcial. Reconhecido pela Resolução CONCEA nº 75/2026 como alternativa à inoculação em camundongos para o diagnóstico da raiva; a inoculação em camundongos só pode ser usada como último recurso, quando as alternativas reconhecidas d