INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('56'::integer, 'european-pharmacopoeia-bacterial-endotoxins-test-recombinant-reagents'::text, 'true'::boolean, '{"en-us": "Test for bacterial endotoxins using recombinant factor C", "pt-br": "Fator C recombinante (rFC) para detecção de endotoxinas bacterianas"}'::jsonb, '{"en-us": "An in vitro method using recombinant factor C (rFC) and fluorimetric detection to detect or quantify bacterial endotoxins without horseshoe crab-derived lysate.", "pt-br": "Método in vitro que utiliza fator C recombinante (rFC) e detecção fluorimétrica para detectar ou quantificar endotoxinas bacterianas sem lisado derivado de caranguejos-ferradura."}'::jsonb, 'none'::text, '["in_chemico"]'::jsonb, NULL, NULL, '10'::integer, 'European Pharmacopoeia'::text, 'validated'::text, NULL, '{"en-us": "Total replacement. Uses recombinant factor C instead of horseshoe crab-derived lysate, avoiding that animal-derived reagent.", "pt-br": "Substituição total. Utiliza fator C recombinante em vez de lisado derivado de caranguejos-ferradura, evitando esse reagente de origem animal."}'::jsonb, NULL, NULL, '{"en-us": ["endotoxin", "recombinant factor C", "rFC", "pyrogenicity", "non-animal"], "pt-br": ["endotoxina", "Fator C recombinante", "rFC", "pirogenicidade", "não animal"]}'::jsonb, 'European Pharmacopoeia: Test for bacterial endotoxins using recombinant factor C. An in vitro method using recombinant factor C (rFC) and fluorimetric detection to detect or quantify bacterial endotoxins without horseshoe crab-derived lysate.'::text, '[0.038229323