INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('53'::integer, 'oecd-tg236-fish-embryo-acute-toxicity-test'::text, 'true'::boolean, '{"en-us": "Fish Embryo Acute Toxicity (FET) Test", "pt-br": "TG 236 - Toxicidade aguda em embrião de peixe (FET)"}'::jsonb, '{"en-us": "An acute toxicity test using zebrafish embryos (Danio rerio) exposed to chemicals for 96 hours to determine lethality based on apical observations.", "pt-br": "Um teste de toxicidade aguda usando embriões de peixe-zebra (Danio rerio) expostos a substâncias químicas por 96 horas para determinar a letalidade com base em observações apicais."}'::jsonb, 'embryos_and_larvae'::text, '["in_vivo"]'::jsonb, 'TG 236'::text, NULL, '45'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The method uses embryonic stages of fish, which are considered a replacement for acute toxicity tests on juvenile or adult fish.", "pt-br": "Substituição parcial. O método utiliza estágios embrionários de peixes, considerados uma alternativa a ensaios de toxicidade aguda com peixes juvenis ou adultos."}'::jsonb, NULL, NULL, '{"en-us": ["zebrafish", "embryo", "acute toxicity", "Danio rerio"], "pt-br": ["peixe-zebra", "embrião", "toxicidade aguda", "Danio rerio"]}'::jsonb, 'OECD TG 236: Fish Embryo Acute Toxicity (FET) Test. An acute toxicity test using zebrafish embryos (Danio rerio) exposed to chemicals for 96 hours to determine lethality based on apical observations.'::text, '[-0.04108710214495659, 0.016294650733470917, -0.035333745181560516, 0.01018521748483181, 0.02983899414539337, -