INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('14'::integer, 'oecd-tg442a-llna-da'::text, 'true'::boolean, '{"en-us": "LLNA: DA — Non-Radioactive Local Lymph Node Assay (ATP)", "pt-br": "TG 442A - Versões não radioativas do Ensaio do Linfonodo Local (ATP)"}'::jsonb, '{"en-us": "The Local Lymph Node Assay: DA (LLNA: DA) is a non-radioactive modification to the LLNA method for identifying potential skin sensitizing test substances by measuring lymphocyte proliferation in auricular lymph nodes via ATP content bioluminescence.", "pt-br": "O Local Lymph Node Assay: DA (LLNA: DA) é uma modificação não radioativa do método LLNA para identificar potenciais substâncias sensibilizantes cutâneas, medindo a proliferação de linfócitos nos linfonodos auriculares através da bioluminescência do conteúdo de ATP."}'::jsonb, 'live_animals'::text, '["in_vivo", "ex_vivo"]'::jsonb, 'TG 442A'::text, NULL, '24'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "Compared with the guinea pig tests (TG 406), the LLNA: DA has the potential to reduce animal use for skin sensitisation testing.", "pt-br": "Em comparação com os testes em cobaias (TG 406), o LLNA: DA tem potencial para reduzir o uso de animais nos testes de sensibilização cutânea."}'::jsonb, '{"en-us": "The LLNA: DA offers a substantial refinement (less pain and distress) in the way animals are used for skin sensitisation testing, an advantage over the guinea pig tests (TG 406).", "pt-br": "O LLNA: DA oferece um refinamento substancial (menos dor e sofrimento) na forma como os animais são usados nos testes de sensibilização cutânea, uma vantagem em relação aos testes em cobaias (TG 406)."}'::jsonb, '{"en-us": ["LLNA: DA", "skin sensitisation", "ATP bioluminescence", "lymphocyte proliferation"], "pt-br": ["LLNA: DA", "sensibilização cutânea", "bioluminescência de ATP", "proliferação linfocitária"]}'::jsonb, 'OECD TG 442A: LLNA: DA - Non-Radioactive Local Lymph Node Assay (ATP). The Local Lymph Node Assay: DA (LLNA: DA) is a non-radioactive modification to the LLNA method for identifying potential skin sensitizing test substances by measuring lymphocyte proliferation in auricular lymph nodes via ATP content bioluminescence.'::text, '[-0.034854549914598465, 0.04904492199420929, -0.016356443986296654, -0.05295168608427048, 0.04163353145122528, -0.0756402388215065, -0.0006136661395430565, 0.04933365061879158, 0.011933917179703712, 0.03661203384399414, 0.026748986914753914, -0.0150499502196908, -0.040270596742630005, 0.04736391827464104, -0.020849080756306648, 0.028293687850236893, -0.0018092500977218151, 0.03956897184252739, 0.03531721979379654, 0.0070028346963226795, 0.020449243485927582, 0.13060295581817627, 0.02239687368273735, -0.04089866951107979, 0.050964247435331345, -0.01891743578016758, 0.0416485071182251, -0.0204776618629694, -0.002216869033873081, -0.02172659896314144, -0.0048004318960011005, 0.011012336239218712, -0.01265721581876278, 0.005464896094053984, -0.06296461075544357, -0.050730038434267044, -0.10023248940706253, 0.0727977305650711, -0.006830920465290546, 0.039301663637161255, 0.07741734385490417, -0.011676285415887833, 0.015972575172781944, 0.04020460322499275, 0.013927982188761234, -0.05537351220846176, -0.07778429239988327, 0.03486614301800728, -0.09018134325742722, 0.07060667872428894, 0.13137200474739075, -0.0679113045334816, -0.06619904190301895, 0.03048531897366047, -0.014240137301385403, 0.006059892941266298, -0.039758630096912384, 0.0004074251919519156, -0.04065556824207306, 0.06858513504266739, 0.06280789524316788, 0.01587013155221939