INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('3'::integer, 'oecd-tg431-in-vitro-skin-corrosion'::text, 'true'::boolean, '{"en-us": "In vitro skin corrosion: reconstructed human epidermis (RHE) test method", "pt-br": "TG 431 - Corrosão dérmica in vitro: Teste da Epiderme Humana Reconstituída (RHE)"}'::jsonb, '{"en-us": "In vitro method that uses a three-dimensional reconstructed human epidermis with a functional stratum corneum to identify corrosive and non-corrosive substances and mixtures based on the reduction in cell viability after defined exposure periods.", "pt-br": "Método in vitro que utiliza epiderme humana reconstruída tridimensional, com estrato córneo funcional, para identificar substâncias e misturas corrosivas e não corrosivas com base na redução da viabilidade celular após períodos definidos de exposição."}'::jsonb, 'mixed_or_variable'::text, '["in_vitro"]'::jsonb, 'TG 431'::text, NULL, '18'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Total replacement. The Test Guideline does not require the use of live animals or animal tissue for the assessment of skin corrosivity.", "pt-br": "Substituição total. A Diretriz de Teste não requer o uso de animais vivos ou tecido animal para a avaliação da corrosividade cutânea."}'::jsonb, NULL, NULL, '{"en-us": ["skin corrosion", "reconstructed human epidermis", "RHE", "cytotoxicity"], "pt-br": ["corrosão cutânea", "epiderme humana reconstruída", "RHE", "citotoxicidade"]}'::jsonb, 'OECD TG 431: In vitro skin corrosion: reconstructed human epidermis (RHE) test method. In vitro method 