INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('41'::integer, 'oecd-tg455-stably-transfected-transactivation-in-vitro-assays'::text, 'true'::boolean, '{"en-us": "Performance-Based Test Guideline for Stably Transfected Transactivation In Vitro Assays to Detect Estrogen Receptor Agonists and Antagonists", "pt-br": "TG 455 - Teste baseado na performance para ensaios in vitro de transativação transfectada estável para detectar agonistas e antagonistas de receptor estrogênico"}'::jsonb, '{"en-us": "Performance-based guideline for in vitro assays with stably transfected cell lines, used to identify substances with agonist or antagonist activity on estrogen receptors through reporter gene transactivation.", "pt-br": "Diretriz baseada em desempenho para ensaios in vitro com linhagens celulares estavelmente transfectadas, utilizados para identificar substâncias com atividade agonista ou antagonista sobre receptores de estrogênio por meio da transativação de gene repórter."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 455'::text, NULL, '35'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The test method allows for the identification of endocrine disrupting chemicals using in vitro assays as an alternative to animal testing.", "pt-br": "Substituição parcial. O método de teste permite a identificação de substâncias químicas desreguladoras endócrinas usando ensaios in vitro como alternativa aos testes em animais."}'::jsonb, NULL, NULL, '{"en-us": ["estrogen receptor", "transactivation", "endocrine disrupt