INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('18'::integer, 'oecd-tg476-in-vitro-mammalian-cell-gene-mutation-tests'::text, 'true'::boolean, '{"en-us": "In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes", "pt-br": "TG 476 - Testes in vitro de mutação gênica de células de mamífero usando os gens Hprt and xprt"}'::jsonb, '{"en-us": "The in vitro mammalian cell gene mutation test can be used to detect gene mutations induced by chemical substances measuring mutation at hypoxanthine-guanine phosphoribosyl transferase (HPRT) and xanthine-guanine phosphoribosyl transferase (XPRT) loci.", "pt-br": "O teste de mutação gênica em células de mamíferos in vitro pode ser usado para detectar mutações gênicas induzidas por substâncias químicas, medindo a mutação nos loci da hipoxantina-guanina fosforribosil transferase (HPRT) e xantina-guanina fosforribosil transferase (XPRT)."}'::jsonb, 'animals_killed_for_tissue'::text, '["in_vitro"]'::jsonb, 'TG 476'::text, NULL, '31'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, NULL, NULL, '{"en-us": ["genotoxicity", "gene mutation", "HPRT", "XPRT", "mammalian cell"], "pt-br": ["genotoxicidade", "mutação gênica", "HPRT", "XPRT", "célula de mamífero"]}'::jsonb, 'OECD TG 476: In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes. The in vitro mammalian cell gene mutation test can be used to detect gene mutations induced by chemical substances measuring mutation at hypoxanthine-guanine phosphoribosyl transferase (HPRT) and xanthine-guanine phosphoribosyl transferase (XPRT) loc