INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('19'::integer, 'oecd-tg487-in-vitro-mammalian-cell-micronucleus-test'::text, 'true'::boolean, '{"en-us": "In Vitro Mammalian Cell Micronucleus Test", "pt-br": "TG 487 - Teste do Micronúcleo em Célula de Mamífero in vitro"}'::jsonb, '{"en-us": "The in vitro micronucleus test is a genotoxicity test for the detection of micronuclei in the cytoplasm of interphase cells, originating from acentric chromosome fragments or whole chromosomes that are unable to migrate to the poles during anaphase.", "pt-br": "O teste de micronúcleo in vitro é um teste de genotoxicidade para a detecção de micronúcleos no citoplasma de células em interfase, originados de fragmentos cromossômicos acêntricos ou cromossomos inteiros que não conseguem migrar para os polos durante a anáfase."}'::jsonb, 'animals_killed_for_tissue'::text, '["in_vitro"]'::jsonb, 'TG 487'::text, NULL, '32'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, NULL, NULL, '{"en-us": ["genotoxicity", "micronucleus", "clastogenic", "aneugenic"], "pt-br": ["genotoxicidade", "micronúcleo", "clastogênico", "aneugênico"]}'::jsonb, 'OECD TG 487: In Vitro Mammalian Cell Micronucleus Test. The in vitro micronucleus test is a genotoxicity test for the detection of micronuclei in the cytoplasm of interphase cells, originating from acentric chromosome fragments or whole chromosomes that are unable to migrate to the poles during anaphase.'::text, '[-0.04166356474161148, 0.07130103558301926, -0.030634496361017227, -0.032852694392204285, 0.01909758523106575, -0.0736658722