INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('1'::integer, 'oecd-tg439-reconstructed-human-epidermis-skin-irritation'::text, 'true'::boolean, '{"en-us": "In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method", "pt-br": "TG 439 - Teste de irritação Cutânea in vitro"}'::jsonb, '{"en-us": "An in vitro procedure using reconstructed human epidermis (RhE) to identify irritant chemicals (substances and mixtures) by measuring cell viability via MTT reduction, mimicking the physiological properties of human skin.", "pt-br": "Procedimento in vitro utilizando epiderme humana reconstruída (RhE) para identificar substâncias químicas irritantes (substâncias e misturas) através da medição da viabilidade celular via redução do MTT, mimetizando as propriedades fisiológicas da pele humana."}'::jsonb, 'mixed_or_variable'::text, '["in_vitro"]'::jsonb, 'TG 439'::text, NULL, '23'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Total or partial replacement. The procedure may be used as a stand-alone replacement test for in vivo skin irritation testing, or as a partial replacement test within a tiered testing strategy.", "pt-br": "Substituição total ou parcial. O procedimento pode ser utilizado como teste substitutivo autônomo para ensaios de irritação cutânea in vivo ou como teste de substituição parcial no âmbito de uma estratégia de ensaios em etapas."}'::jsonb, NULL, NULL, '{"en-us": ["RhE", "skin irritation", "MTT assay", "in vitro"], "pt-br": ["RhE", "irritação cutânea", "ensaio MTT", "in vitro"]}'::jsonb, 'OECD TG 439: In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method. An in vitro procedure using reconstructed human epidermis (RhE) to identify irritant chemicals (substances and mixtures) by measuring cell viability via MTT reduction, mimicking the physiological properties of human skin.'::text, '[-0.0717698484659195, 0.014225466176867485, 0.04786945506930351, 0.01771659404039383, 0.08279485255479813, -0.026300134137272835, 0.09008627384901047, 0.1529325693845749, -0.061246033757925034, 0.026170771569013596, 0.016122890636324883, -0.023860536515712738, 0.0008503381977789104, 0.050556156784296036, -0.06416907161474228, -0.09016997367143631, 0.027088498696684837, 0.04850545525550842, 0.08204226940870285, -0.005569981876760721, 0.03770850971341133, 0.0830622985959053, 0.033389247953891754, -0.02841763384640217, -0.008632236160337925, -0.05504518002271652, 0.009937796741724014, 0.021093934774398804, 0.005264303181320429, -0.027890870347619057, 0.07500765472650528, -0.008758755400776863, -0.03474194183945656, -0.027571264654397964, -0.08262782543897629, 0.0042995791882276535, -0.0430627278983593, -0.01152587216347456, 0.011845670640468597, 0.008579092100262642, 0.04398735612630844, -0.07401715219020844, -0.0634557232260704, -0.052053578197956085, 0.1071072667837143, -0.0031638864893466234, 0.03594689816236496, -0.03825318068265915, -0.10148950666189194, 0.09045267105102539, 0.10057780891656876, -0.0038660115096718073, 0.006164925172924995, -0.023237649351358414, -0.036275092512369156, -0.04955729469656944, -0.04888448491692543, -0.05387595295906067, -0.06754495203495026, 0.01250724121928215, 0.03091508522629738, -0.02517654187977314, 0.019536567851901054, 0.008629964664578438, 0.06551355868577957, -0.03760189563035965, 0.05726691707968712, -0.04153040051460266, 0.04511271044611931, -0.020656147971749306, -0.04590746760368347, 0.011637872084975243, 0.01588151417672634, 0.037442564964294434, 0.012479793280363083, 0.09686321020126343, 0.015525496564805508, -0.0180966854095459, -0.0528064444