INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('34'::integer, 'rabies-virus-isolation-tissue-culture'::text, 'true'::boolean, '{"en-us": "Rabies tissue culture infection test (RTCIT)", "pt-br": "Isolamento viral em cultivo celular (Rabies Tissue Culture Infection Test - RTCIT)"}'::jsonb, '{"en-us": "A diagnostic method for the detection and isolation of rabies virus in suspect animal brain tissue samples using neuroblastoma cell cultures (e.g., N2a), intended to replace the mouse inoculation test.", "pt-br": "Um método diagnóstico para a detecção e isolamento do vírus da raiva em amostras de tecido cerebral de animais suspeitos utilizando culturas de células de neuroblastoma (ex: N2a), com a finalidade de substituir o teste de inoculação em camundongos."}'::jsonb, 'slaughterhouse_byproduct'::text, '["in_vitro"]'::jsonb, NULL, 'World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729'::text, '50'::integer, 'WOAH Terrestrial Manual 2025'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. Wherever possible, virus isolation in cell culture should replace mouse inoculation tests to avoid the use of animals.", "pt-br": "Substituição parcial. Sempre que possível, o isolamento viral em cultura de células deve substituir os testes de inoculação em camundongos para evitar o uso de animais."}'::jsonb, NULL, NULL, '{"en-us": ["rabies", "virus isolation", "cell culture", "RTCIT", "diagnosis"], "pt-br": ["raiva", "isolamento viral", "cultura de células", "RTCIT", "diagnóstico"]}'::jsonb, 'WOAH Terrestrial Manual 2025: Rabies tissue culture infection test (RTCIT). A diagnostic method for the detection and isolation of rabies virus in suspect animal brain tissue samples using neuroblastoma cell cultures (e.g., N2a), intended to replace the mouse inoculation test.'::text, '[-0.05084938555955887, 0.029649067670106888, -0.1011565551161766, -0.0054003228433430195, 0.030710749328136444, -0.046636246144771576, -0.03431287780404091, 0.0376194566488266, -0.047890543937683105, 0.09833469986915588, 0.018284890800714493, -0.027705591171979904, 0.002524084411561489, 0.0707855373620987, -0.14553403854370117, -0.10425600409507751, -0.03841250389814377, -0.057005587965250015, 0.07523229718208313, 0.023367000743746758, -0.09987001866102219, 0.05163847282528877, 0.003272479400038719, -0.07527340948581696, -0.006191804073750973, 0.05261028930544853, 0.0055389623157680035, 0.002182346535846591, 0.06677199900150299, 0.03733416646718979, 0.07570911198854446, -0.015351787209510803, -0.05363965779542923, 0.005734946578741074, -0.022212902083992958, 0.02876235730946064, -0.02627044916152954, 0.00915815494954586, 0.04662671685218811, 0.06123347952961922, 0.017604729160666466, -0.05654728412628174, 0.013897759839892387, -0.02524254284799099, -0.005264394450932741, 0.03109767660498619, -0.059667494148015976, 0.03519199788570404, -0.02977144531905651, -0.05078279227018356, 0.05557820945978165, -0.0014405283145606518, -0.009111558087170124, 0.10485688596963882, -0.04983142763376236, 0.009186021983623505, 0.0021949405781924725, -0.040302492678165436, -0.008099470287561417, 0.07250966131687164, -0.014034869149327278, 0.01727871038019657, -0.003192510921508074, -0.02824310027062893, 0.06929052621126175, -0.040118686854839325, -0.06330599635839462, 0.03973212465643883, 0.07470180839300156, -0.006658643949776888, 0.025847379118204117, 0.03557939454913139, 0.02792456