INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('35'::integer, 'rabies-rt-pcr-diagnostic-assay'::text, 'true'::boolean, '{"en-us": "Pan-lyssavirus reverse-transcription polymerase chain reaction (RT-PCR) assays", "pt-br": "Técnicas moleculares baseadas em Reação de Transcriptase Reversa, seguida de Reação em Cadeia da Polimerase quantitativa (RT-qPCR) ou convencional (RT-PCR)"}'::jsonb, '{"en-us": "Laboratory technique for the detection and identification of lyssavirus RNA in suspect animal brain tissue samples using conventional or real-time reverse-transcription polymerase chain reaction (RT-PCR) assays. Can replace the mouse inoculation test (MIT) for animal rabies diagnosis.", "pt-br": "Técnica laboratorial para detecção e identificação de RNA de lyssavírus em amostras de tecido cerebral animal suspeito, utilizando ensaios de reação em cadeia da polimerase com transcrição reversa (RT-PCR) convencional ou em tempo real. Pode substituir o teste de inoculação em camundongos (Mouse inoculation Test - MIT) para diagnóstico da raiva animal."}'::jsonb, 'slaughterhouse_byproduct'::text, '["in_vitro"]'::jsonb, NULL, 'World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729'::text, '50'::integer, 'WOAH Terrestrial Manual 2025'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. Recognized by CONCEA Resolution 75/2026 as an alternative to mouse inoculation for rabies diagnosis; mouse inoculation is allowed only as a last resort when recognized alternatives leave the diagnosis inconclusive.", "pt-br": "Substituição parcial. Reconhecido pela Resolução CONCEA nº 75/2026 como alternativa à inoculação em camundongos para o diagnóstico da raiva; a inoculação em camundongos só pode ser usada como último recurso, quando as alternativas reconhecidas deixam o diagnóstico inconclusivo."}'::jsonb, NULL, NULL, '{"en-us": ["rabies", "lyssavirus", "RT-PCR", "diagnosis", "molecular diagnostics", "virus detection"], "pt-br": ["raiva", "lyssavirus", "RT-PCR", "diagnóstico", "diagnóstico molecular", "detecção de vírus"]}'::jsonb, 'WOAH Terrestrial Manual 2025: Pan-lyssavirus reverse-transcription polymerase chain reaction (RT-PCR) assays. Laboratory technique for the detection and identification of lyssavirus RNA in suspect animal brain tissue samples using conventional or real-time reverse-transcription polymerase chain reaction (RT-PCR) assays. Can replace the mouse inoculation test (MIT) for animal rabies diagnosis.'::text, '[-0.08261720836162567, -0.024193983525037766, -0.021540667861700058, -0.052077941596508026, 0.11304617673158646, 0.01592499390244484, -0.05240806192159653, 0.0136851342394948, -0.0031193438917398453, 0.08196482062339783, -0.007298737298697233, 0.023289144039154053, -0.043896500021219254, 0.07778530567884445, -0.08051909506320953, -0.039561234414577484, -0.14201867580413818, -0.09492295235395432, 0.08675673604011536, -0.03940172120928764, -0.0681455060839653, 0.08506779372692108, -0.005659433081746101, -0.05189434066414833, -0.002476562513038516, -0.020827259868383408, 0.02912016585469246, -0.034649770706892014, 0.015087895095348358, 0.054795071482658386, 0.035416197031736374, -0.021568777039647102, 0.013516142033040524, -0.015641411766409874, -0.06255418062210083, 0.0009833424119278789, -0.07852411270141602, -0.028545165434479713, 0.06902285665273666, 0.0456305555999279, 0.06495346128940582, -0.055694352835416794, 0.0421