INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('55'::integer, 'oecd-tg319b-rt-s9-intrinsic-clearance'::text, 'true'::boolean, '{"en-us": "Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9)", "pt-br": "TG 319B - Determinação do \"clearance\" intrínseco \"in vitro\" usando fração sub-celular S-9 de Truta Arco-Íris (RT-S9)"}'::jsonb, '{"en-us": "The test guideline describes the use of rainbow trout liver S9 sub-cellular fraction as a metabolising system to determine the in vitro intrinsic clearance of a test chemical using a substrate depletion approach.", "pt-br": "A diretriz de teste descreve o uso da fração subcelular S9 de fígado de truta arco-íris como um sistema metabolizante para determinar o clearance intrínseco in vitro de uma substância química de teste usando uma abordagem de depleção de substrato."}'::jsonb, 'animals_killed_for_tissue'::text, '["in_vitro"]'::jsonb, 'TG 319B'::text, NULL, '47'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "Predicted bioconcentration factors based on in vitro intrinsic clearance can be used as a screening tool to decide whether a full in vivo fish BCF study is warranted; they may not replace in vivo fish bioaccumulation tests.", "pt-br": "Fatores de bioconcentração previstos com base no clearance intrínseco in vitro podem ser usados como ferramenta de triagem para decidir se um estudo completo de BCF in vivo em peixes se justifica; eles podem não substituir os testes de bioacumulação em peixes in vivo."}'::jsonb, NULL, '{"en-us": ["rainbow trout", "S9 fraction", "intrinsic clearance", "metabolism", "substrate depletion"], "pt-br": ["truta arco-íris", "fração S9", "depuração intrínseca", "metabolismo", "depleção de substrato"]}'::jsonb, 'OECD TG 319B: Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9). The test guideline describes the use of rainbow trout liver S9 sub-cellular fraction as a metabolising system to determine the in vitro intrinsic clearance of a test chemical using a substrate depletion approach.'::text, '[-0.046306878328323364, -0.026405535638332367, -0.01825515180826187, -0.055461276322603226, -0.018382642418146133, -0.006922536995261908, -0.01813509128987789, 0.14254052937030792, -0.034632205963134766, -0.04134015366435051, 0.009704879485070705, -0.039147328585386276, -0.0804385393857956, 0.01729743368923664, -0.07698952406644821, -0.04270534589886665, 0.09295324981212616, 0.011477024294435978, -0.03380313143134117, -0.06843236833810806, 0.0031685736030340195, 0.037543874233961105, 0.03445558249950409, 0.029093269258737564, 0.04120210185647011, 0.026349762454628944, -0.05453268438577652, 0.0704725980758667, 0.05040436610579491, -0.013644766062498093, -0.02954651042819023, 0.08371961861848831, 0.05921773239970207, -0.0905594453215599, -0.0808921754360199, -0.041507888585329056, -0.019686825573444366, 0.015311944298446178, 0.014472470618784428, 0.07635418325662613, 0.06080159917473793, -0.008600326254963875, -0.09617551416158676, 0.036136455833911896, -0.014679818414151669, -0.021883323788642883, -0.03774993121623993, -0.028187178075313568, -0.08417723327875137, 0.03992880508303642, 0.04065858572721481, -0.05703243613243103, -0.014118424616754055, 0.055792029947042465, 0.030216051265597343, 0.02705254592001438, -0.04841071367263794, -0.07201702147722244, 0.0014663831098005176, -0.020122386515140533, -0.033168014138936996, -0.07549525797367096, -0.010256662964820862, 0.006761432625353336, 0.10069691389799118, 0.010022547096014023, 