INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('15'::integer, 'oecd-tg442b-llna-brdu-elisa-fcm'::text, 'true'::boolean, '{"en-us": "Skin Sensitization: Local Lymph Node Assay: BrdU-ELISA or -FCM", "pt-br": "TG 442B - Versões não radioativas do Ensaio do Linfonodo Local (BrdU-ELISA or -FCM)"}'::jsonb, '{"en-us": "A non-radioactive modification to the LLNA method for identifying potential skin sensitizing test chemicals by measuring the proliferation of lymphocytes in auricular lymph nodes using BrdU content, either by ELISA or Flow Cytometry.", "pt-br": "Uma modificação não radioativa do método LLNA para identificar produtos químicos com potencial de sensibilização cutânea, medindo a proliferação de linfócitos nos linfonodos auriculares usando o conteúdo de BrdU, seja por ELISA ou Citometria de Fluxo."}'::jsonb, 'live_animals'::text, '["in_vivo", "ex_vivo"]'::jsonb, 'TG 442B'::text, NULL, '25'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "Like other LLNA methods, the LLNA: BrdU-ELISA has the potential to reduce animal use compared with the guinea pig tests (TG 406); not requiring a radiolabel may allow wider use of mice and further reduce the use of guinea pigs.", "pt-br": "Como os demais métodos LLNA, o LLNA: BrdU-ELISA tem potencial para reduzir o uso de animais em comparação com os testes em cobaias (TG 406); por não exigir marcação radioativa, pode ampliar o uso de camundongos e reduzir ainda mais o uso de cobaias."}'::jsonb, '{"en-us": "The LLNA: BrdU-ELISA offers a substantial refinement in the way animals are used for skin sensitisation testing, an advantage over the guinea pig tests (TG 406).", "pt-br": "O LLNA: BrdU-ELISA oferece um refinamento substancial na forma como os animais são usados nos testes de sensibilização cutânea, uma vantagem em relação aos testes em cobaias (TG 406)."}'::jsonb, '{"en-us": ["skin sensitisation", "LLNA", "BrdU", "ELISA", "flow cytometry", "lymph nodes"], "pt-br": ["sensibilização cutânea", "LLNA", "BrdU", "ELISA", "citometria de fluxo", "linfonodos"]}'::jsonb, 'OECD TG 442B: Skin Sensitization: Local Lymph Node Assay: BrdU-ELISA or -FCM. A non-radioactive modification to the LLNA method for identifying potential skin sensitizing test chemicals by measuring the proliferation of lymphocytes in auricular lymph nodes using BrdU content, either by ELISA or Flow Cytometry.'::text, '[0.04637899994850159, -0.01916978880763054, 0.0030380741227418184, 0.00015581892512273043, 0.12690512835979462, -0.004081307910382748, 0.057362623512744904, 0.12461061030626297, -0.07810959964990616, -0.003613340435549617, 0.044730979949235916, -0.09617408365011215, -0.007905959151685238, 0.054729074239730835, -0.02305481769144535, 0.044700175523757935, -0.025393221527338028, -0.010714172385632992, 0.07151788473129272, -0.029694367200136185, -0.05458761006593704, 0.044448480010032654, 0.01807720772922039, 0.01820133440196514, -0.073914535343647, -0.05382189527153969, 0.0417415052652359, -0.002696668729186058, -0.01454853918403387, -0.05599246174097061, 0.03208930045366287, 0.04086657240986824, 0.023750705644488335, 0.018427008762955666, -0.0452120378613472, -0.06132445111870766, -0.07218708097934723, -0.038284458220005035, -0.011203332804143429, 0.03249913454055786, 0.010159087367355824, -0.055631350725889206, -0.019822055473923683, -0.06696358323097229, 0.09162174165248871, -0.026139933615922928, 0.010101632215082645, 0.021855905652046204, -0.12538984417915344, 0.15093152225017548, 0.09770910441875458, -0.023572353646159172, -0.06994981318712234, 0.03519201651215553, -0.02902258