INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('13'::integer, 'oecd-tg429-local-lymph-node-assay'::text, 'true'::boolean, '{"en-us": "Skin Sensitisation: Local Lymph Node Assay", "pt-br": "TG 429 - Sensibilização Cutânea: Ensaio do Linfonodo Local"}'::jsonb, '{"en-us": "The Local Lymph Node Assay (LLNA) is a method for identifying skin sensitizers by measuring the proliferation of lymphocytes in the auricular lymph nodes draining the site of chemical application in mice.", "pt-br": "O Local Lymph Node Assay (LLNA) é um método para identificar sensibilizantes cutâneos medindo a proliferação de linfócitos nos linfonodos auriculares que drenam o local de aplicação química em camundongos."}'::jsonb, 'live_animals'::text, '["in_vivo"]'::jsonb, 'TG 429'::text, NULL, '16'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "A reduced LLNA approach is described as an option which could use up to 40% fewer animals.", "pt-br": "Uma abordagem LLNA reduzida é descrita como uma opção que pode utilizar até 40% menos animais."}'::jsonb, '{"en-us": "The LLNA offers a substantial refinement (less pain and distress) in the way animals are used for skin sensitisation testing, an advantage over the guinea pig tests (TG 406).", "pt-br": "O LLNA oferece um refinamento substancial (menos dor e sofrimento) na forma como os animais são usados nos testes de sensibilização cutânea, uma vantagem em relação aos testes em cobaias (TG 406)."}'::jsonb, '{"en-us": ["skin sensitisation", "LLNA", "mouse", "lymphocyte proliferation"], "pt-br": ["sensibilização cutânea", "