INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('21'::integer, 'oecd-tg428-skin-absorption-in-vitro'::text, 'true'::boolean, '{"en-us": "Skin Absorption: In Vitro Method", "pt-br": "TG 428 - Absorção Cutânea método in vitro"}'::jsonb, '{"en-us": "An in vitro method using diffusion cells with skin samples (human or animal, viable or non-viable) to measure the percutaneous absorption of test substances applied to the skin surface.", "pt-br": "Um método in vitro usando células de difusão com amostras de pele (humana ou animal, viável ou não viável) para medir a absorção percutânea de substâncias de teste aplicadas na superfície da pele."}'::jsonb, 'mixed_or_variable'::text, '["ex_vivo"]'::jsonb, 'TG 428'::text, NULL, '15'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "The method measures skin absorption on excised skin in a diffusion cell, which can reduce the use of live animals compared with the in vivo skin absorption study (TG 427). It is not a full replacement because the skin used is usually obtained from animals.", "pt-br": "O método mede a absorção cutânea em pele excisada, em célula de difusão, o que pode reduzir o uso de animais vivos em comparação com o estudo in vivo de absorção cutânea (TG 427). Não é uma substituição total porque a pele utilizada costuma ser obtida de animais."}'::jsonb, NULL, '{"en-us": ["skin absorption", "diffusion cell", "percutaneous absorption"], "pt-br": ["absorção cutânea", "célula de difusão", "absorção percutânea"]}'::jsonb, 'OECD TG 428: Skin Absorption: In Vitro Method. An in vitro method usi