INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('4'::integer, 'oecd-tg430-ter-corrosion'::text, 'true'::boolean, '{"en-us": "In Vitro Skin Corrosion: Transcutaneous Electrical Resistance Test Method (TER)", "pt-br": "TG 430 - Corrosão dérmica in vitro: Teste de Resistência Elétrica Transcutânea (TER)"}'::jsonb, '{"en-us": "A test method that utilizes rat skin discs to identify corrosives by their ability to produce a loss of normal stratum corneum integrity and barrier function as measured by transcutaneous electrical resistance.", "pt-br": "Um método de teste que utiliza discos de pele de rato para identificar corrosivos pela sua capacidade de produzir uma perda da integridade normal do estrato córneo e da função de barreira, medida através da resistência elétrica transcutânea."}'::jsonb, 'animals_killed_for_tissue'::text, '["ex_vivo"]'::jsonb, 'TG 430'::text, NULL, '17'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The method uses ex vivo skin discs to identify corrosive chemicals, avoiding the use of live animals for this endpoint.", "pt-br": "Substituição parcial. O método utiliza discos de pele ex vivo para identificar produtos químicos corrosivos, evitando o uso de animais vivos para este endpoint."}'::jsonb, NULL, NULL, '{"en-us": ["skin corrosion", "TER", "transcutaneous electrical resistance", "corrosive"], "pt-br": ["corrosão cutânea", "TER", "resistência elétrica transcutânea", "corrosivo"]}'::jsonb, 'OECD TG 430: In Vitro Skin Corrosion: Transcutaneous Electrical Resistance Test Method (TER). A test meth