INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('54'::integer, 'oecd-tg319a-rt-hep-clearance'::text, 'true'::boolean, '{"en-us": "Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP)", "pt-br": "TG 319A - Determinação do \"clearance\" intrínseco \"in vitro\" usando hepatócitos criopreservados de Truta Arco-Íris (RT-HEP)"}'::jsonb, '{"en-us": "This Test Guideline describes the use of cryopreserved rainbow trout (Oncorhynchus mykiss) hepatocytes (RT-HEP) as a metabolising system to determine the intrinsic clearance (CL, IN VITRO, INT) of a test chemical using a substrate depletion approach.", "pt-br": "Esta Diretriz de Teste descreve o uso de hepatócitos de truta arco-íris (Oncorhynchus mykiss) criopreservados (RT-HEP) como um sistema de metabolização para determinar a depuração intrínseca (CL, IN VITRO, INT) de um produto químico de teste usando uma abordagem de depleção de substrato."}'::jsonb, 'animals_killed_for_tissue'::text, '["in_vitro"]'::jsonb, 'TG 319A'::text, NULL, '46'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "Predicted bioconcentration factors based on in vitro intrinsic clearance can be used as a screening tool to decide whether a full in vivo fish BCF study is warranted; they may not replace in vivo fish bioaccumulation tests.", "pt-br": "Fatores de bioconcentração previstos com base no clearance intrínseco in vitro podem ser usados como ferramenta de triagem para decidir se um estudo completo de BCF in vivo em peixes se justifica; eles podem não substituir os testes de bioacumulação em peixes in vivo."}'::jsonb, NULL, '{"en-us": ["rainbow trout", "hepatocytes", "intrinsic clearance", "metabolism", "bioaccumulation", "substrate depletion"], "pt-br": ["truta arco-íris", "hepatócitos", "depuração intrínseca", "metabolismo", "bioacumulação", "depleção de substrato"]}'::jsonb, 'OECD TG 319A: Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP). This Test Guideline describes the use of cryopreserved rainbow trout (Oncorhynchus mykiss) hepatocytes (RT-HEP) as a metabolising system to determine the intrinsic clearance (CL, IN VITRO, INT) of a test chemical using a substrate depletion approach.'::text, '[-0.022480808198451996, -0.0009873600210994482, -0.018295522779226303, -0.031143639236688614, -0.04096857085824013, 0.0234629325568676, 0.001859280513599515, 0.14933525025844574, -0.028499547392129898, -0.008174165152013302, 0.011363671161234379, 0.016604207456111908, -0.05550282076001167, 0.050422303378582, -0.06685850024223328, -0.03233715519309044, 0.07969485223293304, -0.023099279031157494, -0.07415067404508591, -0.08432020246982574, 0.03609398752450943, 0.0260233785957098, -0.05399906262755394, -0.01817924901843071, 0.01972058229148388, 0.0738455206155777, -0.018492698669433594, 0.06404940038919449, 0.05411488562822342, 0.04526255652308464, -0.060785699635744095, 0.06356725841760635, 0.04809248819947243, -0.13782721757888794, -0.03355332836508751, 0.025632789358496666, -0.0318291150033474, -0.01900828443467617, -0.026820726692676544, 0.03598545119166374, 0.05249987170100212, -0.020636074244976044, -0.10016416013240814, 0.00639151968061924, 0.031233733519911766, -0.0039229439571499825, -0.03767503425478935, 0.013597525656223297, -0.07495687901973724, -0.02227596752345562, 0.012466204352676868, -0.023950107395648956, 0.026158960536122322, 0.05553070455789566, 0.02171335183084011, 0.04057838395237923, -0.03846152871847153, -0.09144947677850723, -0.006296733394265175, -0.03557847440242767