"}]'::jsonb, 'in_review'::text);
INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('6'::integer, 'oecd-tg437-bcop'::text, 'true'::boolean, '{"en-us": "Bovine Corneal Opacity and Permeability Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage", "pt-br": "TG 437 - Teste de Permeabilidade e Opacidade de Córnea Bovina"}'::jsonb, '{"en-us": "An ex vivo test method that uses isolated bovine corneas from cattle slaughtered for commercial purposes to identify chemicals inducing serious eye damage or chemicals not requiring classification for eye irritation/damage.", "pt-br": "Um método de teste ex vivo que utiliza córneas bovinas isoladas de gado abatido para fins comerciais para identificar produtos químicos que induzem danos oculares graves ou produtos químicos que não requerem classificação para irritação/dano ocular."}'::jsonb, 'slaughterhouse_byproduct'::text, '["ex_vivo"]'::jsonb, 'TG 437'::text, NULL, '21'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. The BCOP test method avoids the use of laboratory animals by using isolated corneas from the eyes of cattle slaughtered for commercial purposes.", "pt-br": "Substituição parcial. O método de teste BCOP evita o uso de animais de laboratório através do uso de córneas isoladas de olhos de gado abatido para fins comerciais."}'::jsonb, NULL, NULL, '{"en-us": ["BCOP", "ocular toxicity", "cornea", "eye irritation", "serious eye damage"], "pt-br": ["BCOP", "toxicidade ocular", "córnea", "irritação ocular", "dano ocular grave"]}'::jsonb, 'OECD TG 437: Bovine Corneal Opacity and Permeability Test Method for Identifying i) Chemicals Inducing Serious Eye Damage and ii) Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage. An ex vivo test method that uses isolated bovine corneas from cattle slaughtered for commercial purposes to identify chemicals inducing serious eye damage or chemicals not requiring classification for eye irritation/damage.'::text, '[0.004887068644165993, -0.06266722828149796, 0.05885359272360802, 0.004510566126555204, 0.04815961793065071, -0.12005537748336792, 0.08824002742767334, 0.09043992310762405, -0.0495462492108345, 0.045773718506097794, 0.07227148115634918, -0.0010112123563885689, -0.04201338067650795, 0.04820976406335831, -0.12182747572660446, 0.03329351171851158, 0.03472607210278511, 0.0033608865924179554, 0.0732203871011734, -0.005831125192344189, 0.0702546015381813, 0.07162759453058243, -0.013720931485295296, -0.022283511236310005, -0.04199741780757904, -0.05737331509590149, -0.014517147094011307, 0.015432309359312057, -0.0005823650863021612, -0.012177567929029465, -0.04426614195108414, 0.006444593891501427, -0.03018924966454506, -0.003758580656722188, 0.025103067979216576, -0.055534712970256805, 0.011324960738420486, -0.02167692966759205, -0.02924606390297413, 0.04661579430103302, -0.019317874684929848, -0.09579140692949295, -0.05529533326625824, -0.000713069923222065, 0.08757825195789337, 0.03897939622402191, 0.027181146666407585, -0.013805019669234753, -0.07831262052059174, -0.011269300244748592, 0.027847634628415108, -0.0471920408308506, -0.036324307322502136, -0.08255261927843094, -0.025486106052994728, -0.02655908465385437, -0.08941460400819778, -0.009944395162165165, -0.02161811850965023, 0.08503148704767227, 0.011643259786069393, 0.009508578106760979, 0.012387295253574848, 0.02378765307366848, 0.053525350987911224, 0.014873048290610313, 0.0834968313574791, -0.050643499940633774, 0.0007194631034508348, -0.0633