INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('42'::integer, 'oecd-tg493-hrer-binding-assay'::text, 'true'::boolean, '{"en-us": "Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity", "pt-br": "TG 493 - Teste baseado na performance para ensaios in vitro de receptor estrogênico humano recombinante (hrER) para detectar substâncias químicas com afinidade de ligação ER"}'::jsonb, '{"en-us": "A performance-based test guideline for in vitro assays using human recombinant estrogen receptor alpha (ERα) to measure the ability of test chemicals to compete with a radiolabeled ligand for binding to the receptor, thereby identifying potential ER binders.", "pt-br": "Uma diretriz de teste baseada em desempenho para ensaios in vitro utilizando receptor de estrogênio alfa humano recombinante (ERα) para medir a capacidade de substâncias de teste competirem com um ligante radiomarcado pela ligação ao receptor, identificando assim potenciais ligantes do RE."}'::jsonb, 'none'::text, '["in_chemico"]'::jsonb, 'TG 493'::text, NULL, '36'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Partial replacement. Provides an in vitro alternative for identifying estrogen receptor binders, avoiding the use of live animal models for initial screening and prioritization.", "pt-br": "Substituição parcial. Fornece uma alternativa in vitro para a identificação de ligantes do receptor de estrogênio, evitando o uso de modelos animais vivos para triagem inicial e priorização."}'::jsonb, NULL, NULL, '{"en-us": ["estrogen receptor", "endocrine disruption", "binding affinity", "in vitro", "hrER"], "pt-br": ["receptor de estrogênio", "desregulação endócrina", "afinidade de ligação", "in vitro", "hrER"]}'::jsonb, 'OECD TG 493: Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity. A performance-based test guideline for in vitro assays using human recombinant estrogen receptor alpha (ERalpha) to measure the ability of test chemicals to compete with a radiolabeled ligand for binding to the receptor, thereby identifying potential ER binders.'::text, '[0.008880719542503357, -0.04468092322349548, -0.06743708997964859, 0.01166980154812336, 0.017001861706376076, -0.03967937454581261, 0.02281336672604084, 0.094150111079216, 0.04335971176624298, 0.0020874578040093184, -0.025099288672208786, -0.04199254512786865, -0.08555537462234497, 0.04972512647509575, 0.03364894539117813, 0.04309863597154617, 0.007215030025690794, 0.024136969819664955, 0.09298115223646164, -0.030815033242106438, -0.05968973785638809, 0.034367162734270096, 0.01642053946852684, -0.0006599907064810395, -0.06836863607168198, -0.05768810585141182, -0.029266083613038063, 0.03141374886035919, -0.04204215481877327, -0.04908990487456322, 0.06374549865722656, -0.03832452744245529, 0.06625858694314957, 0.04640728235244751, -0.018589457497000694, -0.002345265122130513, 0.007975448854267597, -0.08315300941467285, -0.0314442440867424, 0.04724934697151184, 0.051345352083444595, -0.12466111779212952, -0.016135800629854202, 0.02845820039510727, 0.011710356920957565, -0.023998580873012543, -0.03603949397802353, 0.011565170250833035, -0.08479462563991547, 0.05150889605283737, 0.10838600248098373, -0.07783225178718567, -0.03410696983337402, -0.02392015978693962, -0.039739955216646194, -0.026755481958389282, 0.04205072298645973, -0.06448264420032501, -0.015983041375875473, 0.061787065118551254, -0.00038332014810293913, -0.024031190