INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('46'::integer, 'oecd-tg490-in-vitro-mammalian-cell-gene-mutation-tests'::text, 'true'::boolean, '{"en-us": "In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene", "pt-br": "TG 490 - Testes in vitro de mutação gênica em células de mamífero usando gen Timidinaquinase"}'::jsonb, '{"en-us": "The in vitro mammalian cell gene mutation test using the thymidine kinase (tk) gene involves two distinct assays (MLA using L5178Y tk+/-3.7.2C cells and the TK6 assay using TK6 tk+/- cells) to detect gene mutations and chromosomal events induced by chemical substances in cells exposed with and without metabolic activation.", "pt-br": "O teste de mutação gênica em células de mamíferos in vitro usando o gene da timidina quinase (tk) envolve dois ensaios distintos (MLA usando células L5178Y tk+/-3.7.2C e o ensaio TK6 usando células TK6 tk+/-) para detectar mutações gênicas e eventos cromossômicos induzidos por substâncias químicas em células expostas com e sem ativação metabólica."}'::jsonb, 'animals_killed_for_tissue'::text, '["in_vitro"]'::jsonb, 'TG 490'::text, NULL, '40'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, NULL, NULL, '{"en-us": ["genotoxicity", "gene mutation", "thymidine kinase", "L5178Y", "TK6", "mouse lymphoma assay"], "pt-br": ["genotoxicidade", "mutação gênica", "timidina quinase", "L5178Y", "TK6", "ensaio de linfoma de camundongo"]}'::jsonb, 'OECD TG 490: In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene. The in vitro mammalian cell gene mutation test using the thymidine kinase (tk) gene involves two distinct assays (MLA using L5178Y tk+/-3.7.2C cells and the TK6 assay using TK6 tk+/- cells) to detect gene mutations and chromosomal events induced by chemical substances in cells exposed with and without metabolic activation.'::text, '[-0.078020840883255, 0.07651280611753464, -0.022262325510382652, -0.08010002970695496, 0.047219619154930115, -0.057798612862825394, -0.04953763633966446, 0.07807917892932892, 0.049545325338840485, 0.06453495472669601, 0.005812888033688068, -0.03516051173210144, -0.026539934799075127, -0.05664409324526787, -0.0627908855676651, -0.018024854362010956, -0.06039298698306084, 0.07860775291919708, 0.01563672348856926, -0.12735384702682495, -0.11160200089216232, 0.03862772509455681, 0.04976319521665573, 0.028602750971913338, -0.013489127159118652, -0.05276356637477875, 0.03567614033818245, 0.05560034140944481, -0.03429287299513817, 0.04555685073137283, -0.028551675379276276, 0.02504546381533146, -0.0335908941924572, 0.047059811651706696, -0.01430006418377161, 0.048652492463588715, -0.012674848549067974, -0.007071730215102434, 0.01863871142268181, -0.07867566496133804, 0.06472110003232956, -0.11551841348409653, -0.03269324451684952, 0.04756316915154457, 0.036677949130535126, -0.02853677235543728, -0.010566088370978832, -0.030638044700026512, -0.08128581941127777, 0.11711525171995163, 0.028212320059537888, -0.024458004161715508, -0.056828103959560394, -0.056275032460689545, -0.05750665068626404, -0.029200071468949318, 0.016803566366434097, 0.010738465934991837, 0.09239570796489716, 0.08847592025995255, 0.0025083317887037992, -0.07084497064352036, 0.03503212705254555, 0.0171990804374218, 0.08064309507608414, 0.03116518259048462, 0.07339183986186981, -0.08635362237691879, 0.0007730723591521382, -0.07925260066986084, 0.0039427378214895725, 0.011337987147271633, 0.05557769909501076, 0.05650510638952255, -0.08711575716733932, 0.04951350390911102, -0.04159259796142578, 0.02032787911593914, 0.05