INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('24'::integer, 'oecd-tg423-acute-oral-toxicity-acute-toxic-class-method'::text, 'true'::boolean, '{"en-us": "Acute Oral Toxicity – Acute Toxic Class Method", "pt-br": "TG 423 - Toxicidade Aguda Oral – Classe Tóxica Aguda"}'::jsonb, '{"en-us": "A stepwise procedure with the use of 3 animals of a single sex per step, designed to rank substances for classification purposes and hazard assessment using fixed doses.", "pt-br": "Um procedimento em etapas com o uso de 3 animais de um único sexo por etapa, projetado para classificar substâncias para fins de classificação e avaliação de perigo usando doses fixas."}'::jsonb, 'live_animals'::text, '["in_vivo"]'::jsonb, 'TG 423'::text, NULL, '13'::integer, 'OECD_TG'::text, 'validated'::text, NULL, NULL, '{"en-us": "The method uses a stepwise procedure with a minimum number of animals per step and is able to rank substances while using very few animals compared to conventional acute toxicity tests.", "pt-br": "O método utiliza um procedimento em etapas com um número mínimo de animais por etapa e é capaz de classificar substâncias utilizando muito poucos animais em comparação com os testes convencionais de toxicidade aguda."}'::jsonb, NULL, '{"en-us": ["acute oral toxicity", "LD50", "hazard classification", "fixed dose"], "pt-br": ["toxicidade oral aguda", "DL50", "classificação de perigo", "dose fixa"]}'::jsonb, 'OECD TG 423: Acute Oral Toxicity - Acute Toxic Class Method. A stepwise procedure with the use of 3 animals of a single sex per step, designed to rank substance