INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('16'::integer, 'oecd-tg432-3t3-nru-phototoxicity'::text, 'true'::boolean, '{"en-us": "In Vitro 3T3 NRU Phototoxicity Test", "pt-br": "TG 432 - Teste de Fototoxicidade in vitro 3T3 NRU"}'::jsonb, '{"en-us": "A method to evaluate phototoxicity by comparing the relative reduction in viability of Balb/c 3T3 cells (murine fibroblast cell line) exposed to chemicals in the presence versus absence of light using the Neutral Red uptake assay.", "pt-br": "Um método para avaliar a fototoxicidade comparando a redução relativa na viabilidade de células Balb/c 3T3 (linhagem de fibroblastos murinos) expostas a substâncias químicas na presença versus ausência de luz usando o ensaio de captação de Vermelho Neutro."}'::jsonb, 'animal_derived_material'::text, '["in_vitro"]'::jsonb, 'TG 432'::text, NULL, '19'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Total replacement. The test provides an alternative to in vivo phototoxicity testing by using in vitro cell cultures to assess chemical-induced cytotoxicity following irradiation.", "pt-br": "Substituição total. O teste fornece uma alternativa aos testes de fototoxicidade in vivo usando culturas celulares in vitro para avaliar a citotoxicidade induzida por substâncias químicas após irradiação."}'::jsonb, NULL, NULL, '{"en-us": ["phototoxicity", "Neutral Red Uptake", "3T3 cells", "photo-cytotoxicity"], "pt-br": ["fototoxicidade", "captação de vermelho neutro", "células 3T3", "foto-citotoxicidade"]}'::jsonb, 'OECD TG 432: In Vitro 3T3 NRU Phototoxicity Test. A 