INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable", "animal_procedures_avoided", "review_status") VALUES ('39'::integer, 'oecd-tg492b-rhce-eye-hazard'::text, 'true'::boolean, '{"en-us": "Reconstructed Human Cornea-like Epithelium (RhCE) Test Method for Eye Hazard Identification", "pt-br": "TG 492B - Epitélio semelhante à córnea humano reconstruído (Reconstructed Human Cornea-like Epithelium (RhCE) Test Method for Eye Hazard Identification)"}'::jsonb, '{"en-us": "An in vitro procedure using Reconstructed Human Cornea-like Epithelium (RhCE) to identify chemicals not requiring classification, requiring classification for eye irritation (Cat 2), or serious eye damage (Cat 1) according to UN GHS, based on the MTT cytotoxicity assay.", "pt-br": "Procedimento in vitro utilizando Epitélio Corneano Humano Reconstruído (RhCE) para identificar substâncias que não requerem classificação, que requerem classificação para irritação ocular (Cat 2) ou dano ocular grave (Cat 1) de acordo com o GHS da ONU, baseado no ensaio de citotoxicidade MTT."}'::jsonb, NULL, '["in_vitro"]'::jsonb, 'TG 492B'::text, NULL, '9'::integer, 'OECD_TG'::text, 'validated'::text, NULL, '{"en-us": "Total replacement. Designed to provide an in vitro alternative for the identification of eye hazard categories without the need for animal testing.", "pt-br": "Substituição total. Projetado para fornecer uma alternativa in vitro para a identificação de categorias de perigo ocular sem a necessidade de testes em animais."}'::jsonb, NULL, NULL, '{"en-us": ["RhCE", "eye irritation", "serious eye damage", "MTT assay", "in vitro", "UN GHS"], "pt-br": ["RhCE", "irri